class ModuleErrorBoundary extends React.Component<
  { children: React.ReactNode; label: string },
  { error: Error | null }
> {
  state = { error: null as Error | null };

  static getDerivedStateFromError(error: Error) {
    return { error };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error(
      `[renderer:module-error] ${this.props.label}: ${error.message}`,
      error,
      info.componentStack,
    );
  }

  render() {
    if (!this.state.error) return this.props.children;
    return (
      <div className="flex h-full min-h-0 items-center justify-center bg-[#F9FAFB] px-6">
        <div className="w-full max-w-[560px] rounded-3xl border border-rose-100 bg-white p-6 shadow-sm">
          <p className="text-[11px] font-bold uppercase tracking-[0.18em] text-rose-500">Module unavailable</p>
          <h2 className="mt-2 text-[20px] font-bold text-gray-900">{this.props.label}暂时无法显示</h2>
          <p className="mt-3 text-[13px] leading-6 text-gray-600">
            当前模块的数据结构或加载状态异常，其他功能仍可继续使用。你可以重试当前模块。
          </p>
          <p className="mt-3 rounded-xl bg-rose-50 px-3 py-2 text-[12px] text-rose-700">
            {this.state.error.message}
          </p>
          <button
            type="button"
            onClick={() => this.setState({ error: null })}
            className="mt-4 rounded-xl bg-[#5B7BFE] px-4 py-2 text-[12px] font-bold text-white"
          >
            重试当前模块
          </button>
        </div>
      </div>
    );
  }
}

