const ACTIVE_WORKING_DOCUMENTS_LIMIT = 5;

// inline editor 草稿(Tier 1) — 钢笔新建空白文档时启用,localStorage 自动保存防止丢失。
// 1 个客户对应 1 份草稿,新建会覆盖旧的。保存到项目文档库成功后清掉。
const INLINE_EDITOR_DRAFT_STORAGE_KEY_PREFIX = 'yiyu.workspace.inlineEditorDraft.v1.';
const INLINE_EDITOR_DRAFT_MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000; // 7 天

type InlineEditorDraft = {
  content: string;
  title: string;
  updatedAt: number;
};

type PendingChatImage = {
  id: string;
  name: string;
  mimeType: string;
  dataUrl: string;
  size: number;
};

function readInlineEditorDraft(clientId: string): InlineEditorDraft | null {
  if (!clientId) return null;
  try {
    const raw = window.localStorage.getItem(INLINE_EDITOR_DRAFT_STORAGE_KEY_PREFIX + clientId);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as InlineEditorDraft;
    if (!parsed || typeof parsed !== 'object') return null;
    if (typeof parsed.content !== 'string' || typeof parsed.title !== 'string') return null;
    // 太老的草稿直接当不存在(避免 7 天前的孤立草稿一直弹出来)
    if (typeof parsed.updatedAt === 'number' && Date.now() - parsed.updatedAt > INLINE_EDITOR_DRAFT_MAX_AGE_MS) {
      window.localStorage.removeItem(INLINE_EDITOR_DRAFT_STORAGE_KEY_PREFIX + clientId);
      return null;
    }
    // 内容空也当没草稿,避免回到空草稿白白触发"已恢复"banner
    if (!parsed.content.trim() && !parsed.title.trim()) return null;
    return parsed;
  } catch {
    return null;
  }
}

function writeInlineEditorDraft(clientId: string, content: string, title: string): void {
  if (!clientId) return;
  try {
    const payload: InlineEditorDraft = { content, title, updatedAt: Date.now() };
    window.localStorage.setItem(
      INLINE_EDITOR_DRAFT_STORAGE_KEY_PREFIX + clientId,
      JSON.stringify(payload),
    );
  } catch {
    // localStorage 满了或被禁用,忽略
  }
}

function clearInlineEditorDraft(clientId: string): void {
  if (!clientId) return;
  try {
    window.localStorage.removeItem(INLINE_EDITOR_DRAFT_STORAGE_KEY_PREFIX + clientId);
  } catch {
    // ignore
  }
}

type RecentUsedDocument = {
  documentId: string;
  title: string;
  path: string;
  usedAt: number;
};

const RECENT_USED_DOCUMENTS_STORAGE_KEY = 'yiyu.workspace.recentUsedDocuments.v1';
const RECENT_USED_DOCUMENTS_LIMIT = 30;

// 录音 → 会议纪要的跨 scope 桥接：录音 onComplete 在 App level，会议纪要
// textarea 的 state 在 TasksView 内部。用一个 module-level Map 暂存最近一次
// 录音完成时生成的纪要 markdown，TasksView 打开对应任务时取出并填进 textarea。
// 同时配合 window CustomEvent，让 task modal 当前已打开的情况下立刻填充。

// 客户工作台「问题排队」和「合集导出」的跨挂载持久存储。
// ClientWorkspaceView 在切顶栏 tab 时会 unmount/remount，所有内部 useState 都会重置；
// 用 module-level Map 持有以保住"用户排过的题目/挑过的段落"在切走再回来后不丢。
//
// 重要：Map 实例必须挂到 globalThis 上而不是普通 module-level const。
// 原因：dev mode vite HMR / full-reload 会重新执行 module 顶层代码，
// 普通 `const x = new Map()` 在每次 HMR 都会生成一个新 Map，导致用户排队的题目消失。
// 挂 globalThis 后，新 module instance 会复用上一份 Map，状态跨 HMR 持久。
type WorkspaceQueueListener = () => void;
const QUESTION_QUEUE_MAX_GLOBAL = 10;

interface _YiyuPersistedQueueState {
  questionQueueByClient?: Map<string, string[]>;
  questionQueueListeners?: Set<WorkspaceQueueListener>;
  exportBagByClient?: Map<string, string[]>;
  exportBagListeners?: Set<WorkspaceQueueListener>;
}
const _yiyuPersistedQueue: _YiyuPersistedQueueState =
  ((globalThis as unknown as { __yiyuPersistedQueue?: _YiyuPersistedQueueState }).__yiyuPersistedQueue ||=
    {} as _YiyuPersistedQueueState);

// 把 Map 序列化为 {clientId: string[]} 存进 localStorage；空 Map 直接 removeItem。
const _QUEUE_LS_KEY = 'yiyu.workspace.questionQueueByClient.v1';
const _EXPORT_LS_KEY = 'yiyu.workspace.exportBagByClient.v1';

function _hydrateMapFromLocalStorage(key: string): Map<string, string[]> {
  try {
    const raw = window.localStorage.getItem(key);
    if (!raw) return new Map();
    const parsed = JSON.parse(raw) as Record<string, string[]>;
    const map = new Map<string, string[]>();
    for (const [k, v] of Object.entries(parsed)) {
      if (Array.isArray(v) && v.every((item) => typeof item === 'string')) {
        if (v.length > 0) map.set(k, v);
      }
    }
    return map;
  } catch {
    return new Map();
  }
}
function _persistMapToLocalStorage(key: string, map: Map<string, string[]>): void {
  try {
    if (map.size === 0) {
      window.localStorage.removeItem(key);
      return;
    }
    const obj: Record<string, string[]> = {};
    for (const [k, v] of map) obj[k] = v;
    window.localStorage.setItem(key, JSON.stringify(obj));
  } catch {
    // localStorage 写失败（quota / 无 window）静默
  }
}

const workspaceQuestionQueueByClient: Map<string, string[]> =
  _yiyuPersistedQueue.questionQueueByClient ||= _hydrateMapFromLocalStorage(_QUEUE_LS_KEY);
const workspaceQuestionQueueListeners: Set<WorkspaceQueueListener> =
  _yiyuPersistedQueue.questionQueueListeners ||= new Set<WorkspaceQueueListener>();

function notifyWorkspaceQuestionQueueListeners(): void {
  for (const listener of workspaceQuestionQueueListeners) listener();
}
function getWorkspaceQuestionQueue(clientId: string): string[] {
  return workspaceQuestionQueueByClient.get(clientId) || [];
}
function setWorkspaceQuestionQueue(clientId: string, next: string[]): void {
  if (next.length === 0) workspaceQuestionQueueByClient.delete(clientId);
  else workspaceQuestionQueueByClient.set(clientId, next);
  _persistMapToLocalStorage(_QUEUE_LS_KEY, workspaceQuestionQueueByClient);
  notifyWorkspaceQuestionQueueListeners();
}

const workspaceExportBagByClient: Map<string, string[]> =
  _yiyuPersistedQueue.exportBagByClient ||= _hydrateMapFromLocalStorage(_EXPORT_LS_KEY);
const workspaceExportBagListeners: Set<WorkspaceQueueListener> =
  _yiyuPersistedQueue.exportBagListeners ||= new Set<WorkspaceQueueListener>();

function notifyWorkspaceExportBagListeners(): void {
  for (const listener of workspaceExportBagListeners) listener();
}
function getWorkspaceExportBag(clientId: string): string[] {
  return workspaceExportBagByClient.get(clientId) || [];
}
function setWorkspaceExportBag(clientId: string, next: string[]): void {
  if (next.length === 0) workspaceExportBagByClient.delete(clientId);
  else workspaceExportBagByClient.set(clientId, next);
  _persistMapToLocalStorage(_EXPORT_LS_KEY, workspaceExportBagByClient);
  notifyWorkspaceExportBagListeners();
}

function readStoredRecentUsedDocuments(clientId: string): RecentUsedDocument[] {
  if (!clientId || typeof window === 'undefined') return [];
  try {
    const raw = window.localStorage.getItem(RECENT_USED_DOCUMENTS_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as Record<string, RecentUsedDocument[]>;
    const list = Array.isArray(parsed?.[clientId]) ? parsed[clientId] : [];
    return list
      .filter((item) =>
        item
        && typeof item.documentId === 'string'
        && typeof item.title === 'string'
        && typeof item.path === 'string'
        && typeof item.usedAt === 'number',
      )
      .slice(0, RECENT_USED_DOCUMENTS_LIMIT);
  } catch {
    return [];
  }
}

function writeStoredRecentUsedDocuments(clientId: string, docs: RecentUsedDocument[]) {
  if (!clientId || typeof window === 'undefined') return;
  try {
    const raw = window.localStorage.getItem(RECENT_USED_DOCUMENTS_STORAGE_KEY);
    const parsed = raw ? (JSON.parse(raw) as Record<string, RecentUsedDocument[]>) : {};
    parsed[clientId] = docs.slice(0, RECENT_USED_DOCUMENTS_LIMIT);
    window.localStorage.setItem(RECENT_USED_DOCUMENTS_STORAGE_KEY, JSON.stringify(parsed));
  } catch {
    // ignore
  }
}

function normalizeWorkingDocumentStatus(value?: string | null): ActiveWorkingDocument['status'] {
  if (value === 'ready' || value === 'partial_ready' || value === 'failed') return value;
  if (value === 'queued') return 'queued';
  return 'processing';
}

const TECHNICAL_FAILURE_MARKERS: readonly string[] = [
  'validation error for',
  'Traceback',
  'errors.pydantic.dev',
  'Input should be',
  'pydantic_core',
  "<class '",
];

const KNOWN_FAILURE_TAGS: Record<string, string> = {
  internal_error: '回答过程出现了系统错误，请重试一次。',
  user_canceled: '已取消生成。',
  chat_executor_unavailable: '后台执行器暂不可用，请稍后重试。',
  ai_result_unavailable: 'AI 暂时无法生成回答，请稍后重试。',
  llm_local_fallback_after_retry: '在线模型不可用，已自动退回本地兜底回答。',
  llm_partial_preserved_after_stale_recovery: '上次回答中断，已保留部分内容，请重试以获取完整回答。',
  no_relevant_materials: '当前客户资料中没有命中相关内容。',
};

// 报错分类(UX): 把报错分成「系统问题」(该重试/等一下/找管理员)和「操作问题」(用户自己能改),
// 让用户一眼知道是谁的问题、下一步该干嘛。统一在 showGlobalBanner 入口调用,覆盖全部报错。
type ErrorKind = 'system' | 'user' | 'unknown';

// 系统问题信号: 连接/超时/服务/内部异常/数据库/HTTP 5xx —— 不是用户操作能解决的
const SYSTEM_ERROR_MARKERS: readonly string[] = [
  '无法连接', '连接失败', '连不上', '超时', 'timeout', 'timed out',
  'ECONNREFUSED', 'Failed to fetch', 'NetworkError', '网络',
  '500', '502', '503', '504', 'Internal Server Error', 'Bad Gateway',
  'executor', 'unavailable', '不可用', '后端', '服务未', '服务异常',
  'no such column', 'no such table', 'OperationalError', 'sqlite',
  'NameError', 'AttributeError', 'KeyError', 'TypeError',
];

// 操作问题信号: 必填/格式/重复/无效 —— 用户检查输入就能解决
const USER_ERROR_MARKERS: readonly string[] = [
  '必填', '不能为空', '未填写', '请填写', '请输入', '请选择', '至少', '最多',
  '格式不', '格式错', '不合法', '无效', 'invalid', 'required', 'must be',
  '已存在', '重复', 'duplicate', '已被占用', '超出', '超过', '太长', '太短',
  'too long', 'too short', '不支持', '只支持', '请先', '尚未',
];

function classifyError(raw: string | null | undefined): { kind: ErrorKind; message: string } {
  const text = (raw || '').trim();
  if (!text) return { kind: 'unknown', message: '出了点小问题，请重试一次。' };
  if (KNOWN_FAILURE_TAGS[text]) {
    // "已取消/无命中内容" 既非系统故障也非用户错误 → 中性提示, 不强标系统/操作
    const neutral = text === 'no_relevant_materials' || text === 'user_canceled';
    return { kind: neutral ? 'unknown' : 'system', message: KNOWN_FAILURE_TAGS[text] };
  }
  // 校验类堆栈(pydantic/validation): 本质是用户填的信息有问题, 换成人话
  if (TECHNICAL_FAILURE_MARKERS.some((m) => text.includes(m))) {
    if (/(validation|Input should be|field required|pydantic)/i.test(text)) {
      return { kind: 'user', message: '填写的信息有点问题（可能必填项空着或格式不对），检查一下再提交。' };
    }
    return { kind: 'system', message: '软件内部出错了（不是你的操作），请重试一次；如果反复出现，截图反馈给我们。' };
  }
  if (USER_ERROR_MARKERS.some((m) => text.includes(m))) {
    // 短中文本身已是人话就保留, 太长/英文则给通用操作提示
    const readable = text.length <= 60 && /[一-龥]/.test(text);
    return { kind: 'user', message: readable ? text : '提交的信息有点问题，检查一下必填项和格式再试。' };
  }
  if (SYSTEM_ERROR_MARKERS.some((m) => text.includes(m)) || text.length > 200 || text.includes('\n')) {
    return { kind: 'system', message: '系统暂时出问题了（连接或服务异常，不是你的操作），稍等几秒再重试一次。' };
  }
  // 认不出: 原样保留(多是已写好的中文短句), 不强行归类
  return { kind: 'unknown', message: text };
}

function friendlyFailureMessage(raw: string | null | undefined, fallback = '请稍后重试。'): string {
  const text = (raw || '').trim();
  if (!text) return fallback;
  return classifyError(text).message;
}

function mergeActiveWorkingDocuments(
  incoming: ActiveWorkingDocument[],
  existing: ActiveWorkingDocument[],
) {
  const seen = new Set<string>();
  const merged: ActiveWorkingDocument[] = [];
  for (const item of [...incoming, ...existing]) {
    const documentId = String(item.documentId || '').trim();
    if (!documentId || seen.has(documentId)) continue;
    seen.add(documentId);
    merged.push({ ...item, documentId });
    if (merged.length >= ACTIVE_WORKING_DOCUMENTS_LIMIT) break;
  }
  return merged;
}

function buildActiveWorkingDocumentsFromImports(importResults: ImportRecord[]) {
  const timestamp = Date.now();
  const docs: ActiveWorkingDocument[] = [];
  for (const result of importResults) {
    for (const document of result.documents || []) {
      const documentId = String(document.documentId || '').trim();
      if (!documentId) continue;
      docs.push({
        documentId,
        title: document.title || document.fileName || '资料',
        fileName: document.fileName || document.title || '资料',
        path: document.path || '',
        importId: result.id,
        jobId: result.jobId || null,
        status: normalizeWorkingDocumentStatus(result.status === 'failed' ? 'failed' : result.status),
        preview: null,
        lastError: null,
        updatedAt: timestamp,
      });
    }
  }
  return docs;
}

function readStoredActiveWorkingDocuments(clientId: string) {
  if (typeof window === 'undefined' || !clientId) return [];
  try {
    const raw = window.sessionStorage.getItem(ACTIVE_WORKING_DOCUMENTS_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    const stored = Array.isArray(parsed?.[clientId]) ? parsed[clientId] : [];
    const now = Date.now();
    return stored
      .filter((item: Partial<ActiveWorkingDocument>) =>
        item?.documentId
        && typeof item.updatedAt === 'number'
        && now - item.updatedAt <= ACTIVE_WORKING_DOCUMENTS_MAX_AGE_MS,
      )
      .slice(0, ACTIVE_WORKING_DOCUMENTS_LIMIT) as ActiveWorkingDocument[];
  } catch {
    return [];
  }
}

function writeStoredActiveWorkingDocuments(clientId: string, docs: ActiveWorkingDocument[]) {
  if (typeof window === 'undefined' || !clientId) return;
  try {
    const raw = window.sessionStorage.getItem(ACTIVE_WORKING_DOCUMENTS_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    const next = {
      ...(parsed && typeof parsed === 'object' ? parsed : {}),
      [clientId]: docs.slice(0, ACTIVE_WORKING_DOCUMENTS_LIMIT),
    };
    window.sessionStorage.setItem(ACTIVE_WORKING_DOCUMENTS_STORAGE_KEY, JSON.stringify(next));
  } catch {
    // Session recovery is best-effort; chat still works without it.
  }
}

