function inferPersonalTaskKeywordLabels(title: string, desc: string) {
  const haystack = `${title}\n${desc}`.trim();
  if (!haystack) return [];
  return PERSONAL_TASK_KEYWORD_RULES
    .filter((rule) => rule.pattern.test(haystack))
    .map((rule) => rule.label);
}

