function isWorkspaceAnalysisRunPending(run: ClientAnalysisRun | null | undefined): run is ClientAnalysisRun {
  return Boolean(run && (run.status === 'queued' || run.status === 'running'));
}

function formatElapsedLabel(milliseconds?: number) {
  const safeValue = Math.max(milliseconds || 0, 0);
  return `${(safeValue / 1000).toFixed(1)} 秒`;
}

function mergeDisplayMessages(existingMessages: DisplayChatMessage[], incomingMessages: DisplayChatMessage[]) {
  const messageMap = new Map<string, DisplayChatMessage>();
  for (const item of existingMessages) {
    messageMap.set(item.id, item);
  }
  for (const item of incomingMessages) {
    const existing = messageMap.get(item.id);
    messageMap.set(
      item.id,
      existing
        ? {
            ...existing,
            ...item,
            requestPrompt: item.requestPrompt ?? existing.requestPrompt,
            retrievalSummary:
              item.role === 'assistant'
                ? {
                    ...(existing.retrievalSummary || {}),
                    ...(item.retrievalSummary || {}),
                  }
                : item.retrievalSummary,
          }
        : item,
    );
  }
  return Array.from(messageMap.values()).sort((left, right) => left.createdAt.localeCompare(right.createdAt));
}

function resolveLoadingPhase(summary?: Record<string, unknown> | null) {
  const raw = typeof summary?.phase === 'string' ? summary.phase : '';
  if (raw === 'retrieving' || raw === 'grounding' || raw === 'generating' || raw === 'completed' || raw === 'failed') {
    return raw;
  }
  const master = Number(summary?.masterHitCount || 0);
  const surrogate = Number(summary?.surrogateHitCount || 0);
  const rawChunk = Number(summary?.rawChunkHitCount || 0);
  return master > 0 || surrogate > 0 || rawChunk > 0 ? 'generating' : 'retrieving';
}

function loadingPhaseBounds(summary?: Record<string, unknown> | null) {
  const phase = resolveLoadingPhase(summary);
  const defaultBounds =
    phase === 'retrieving'
      ? { floor: 0, ceiling: 25 }
      : phase === 'grounding'
        ? { floor: 25, ceiling: 55 }
        : phase === 'generating'
          ? { floor: 55, ceiling: 92 }
          : { floor: 100, ceiling: 100 };
  const floor = Number(summary?.progressFloor);
  const ceiling = Number(summary?.progressCeiling);
  return {
    floor: Number.isFinite(floor) ? floor : defaultBounds.floor,
    ceiling: Number.isFinite(ceiling) ? ceiling : defaultBounds.ceiling,
  };
}

function loadingProgressValue(summary: Record<string, unknown> | null | undefined, elapsedMs: number) {
  const phase = resolveLoadingPhase(summary || null);
  if (phase === 'completed' || phase === 'failed') return 100;
  const { floor, ceiling } = loadingPhaseBounds(summary || null);
  const baseline = Math.max(floor, Math.min(Number(summary?.progress || floor), ceiling));
  const phaseSpan = Math.max(ceiling - floor, 0);
  if (phaseSpan <= 0) return baseline;
  const timeConstant = phase === 'retrieving' ? 1800 : phase === 'grounding' ? 2600 : 12000;
  const dynamic = floor + phaseSpan * (1 - Math.exp(-Math.max(elapsedMs, 0) / timeConstant));
  return Math.max(baseline, Math.min(dynamic, ceiling));
}

function loadingStageText(summary?: Record<string, unknown> | null, modelLabel = '当前模型') {
  const explicitLabel = typeof summary?.stageLabel === 'string' ? summary.stageLabel.trim() : '';
  if (explicitLabel) return explicitLabel;
  if (!summary) return '庆华正在整理背景材料，并组织分析答案';
  const master = Number(summary.masterHitCount || 0);
  const surrogate = Number(summary.surrogateHitCount || 0);
  const rawChunk = Number(summary.rawChunkHitCount || 0);
  if (master > 0 || surrogate > 0 || rawChunk > 0) {
    return `庆华已经整理好当前问题所需的背景材料，正在调用${modelLabel}组织完整分析`;
  }
  if (summary.failureReason) {
    return `背景整理阶段提示：${String(summary.failureReason)}`;
  }
  return '庆华正在整理背景材料，并组织分析答案';
}

function loadingSubText(summary?: Record<string, unknown> | null, modelLabel = '当前模型') {
  if (!summary) return `消息已发送。系统会先整理最相关的背景材料，再调用${modelLabel}生成更完整、更专业的顾问式回答。`;
  const phase = resolveLoadingPhase(summary);
  const master = Number(summary.masterHitCount || 0);
  const surrogate = Number(summary.surrogateHitCount || 0);
  const rawChunk = Number(summary.rawChunkHitCount || 0);
  if (phase === 'generating' || master > 0 || surrogate > 0 || rawChunk > 0) {
    return `背景材料已经整理完成。当前阶段主要耗时在${modelLabel}组织最终答案，而不是本地资料定位。`;
  }
  return `消息已发送。系统会先整理最相关的背景材料，再调用${modelLabel}生成更完整、更专业的顾问式回答。`;
}

function loadingPreviewText(summary?: Record<string, unknown> | null) {
  const preview = typeof summary?.previewSummary === 'string' ? summary.previewSummary.trim() : '';
  return preview;
}

function stageLabelForUi(stage?: string | null) {
  if (stage === 'master_index') return '目录概览';
  if (stage === 'surrogate') return '背景摘要';
  if (stage === 'raw_chunk') return '原文片段';
  return stage || '资料';
}

function renderInlineEmphasis(text: string) {
  const parts = text.split(/(\*\*[^*]+\*\*)/g);
  return parts.map((part, index) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      return <strong key={`${part}-${index}`} className="font-semibold text-slate-950">{part.slice(2, -2)}</strong>;
    }
    return <React.Fragment key={`${part}-${index}`}>{part}</React.Fragment>;
  });
}

type AnswerBlock =
  | { type: 'title'; text: string }
  | { type: 'heading'; text: string }
  | { type: 'subheading'; text: string }
  | { type: 'paragraph'; text: string }
  | { type: 'list'; items: string[]; ordered: boolean }
  | { type: 'table'; header: string[]; rows: string[][] };

// R8.14: 探测是否是 markdown 表格行：以 | 开头、以 | 结尾、中间至少有一个 |
function isTableRow(line: string): boolean {
  const trimmed = line.trim();
  if (!trimmed.startsWith('|') || !trimmed.endsWith('|')) return false;
  // 至少要有 2 个 | 把内容分成至少 1 列
  return (trimmed.match(/\|/g) || []).length >= 2;
}

// 切分一行 markdown 表格行为单元格数组
function splitTableRow(line: string): string[] {
  const trimmed = line.trim();
  // 去掉首尾的 |，按 | 切分
  const inner = trimmed.slice(1, -1);
  return inner.split('|').map((cell) => cell.trim());
}

// 探测是否是分隔行（`| --- | --- |` 或 `| :---: | :---- |`）
function isTableSeparatorRow(line: string): boolean {
  if (!isTableRow(line)) return false;
  return splitTableRow(line).every((cell) => /^:?-{3,}:?$/.test(cell));
}

function parseAnswerBlocks(text: string): AnswerBlock[] {
  let cleaned = normalizeAnswerTextForDisplay(text);
  if (!cleaned) return [];
  if (!cleaned.includes('\n\n') && cleaned.split('\n').filter((line) => line.trim()).length >= 3) {
    cleaned = cleaned.replace(/\n+/g, '\n\n');
  }
  const lines = cleaned.split('\n');
  const blocks: AnswerBlock[] = [];
  const firstNonEmptyIndex = lines.findIndex((line) => line.trim());
  const firstNonEmptyLine = firstNonEmptyIndex >= 0 ? lines[firstNonEmptyIndex].trim() : '';
  const visibleLineCount = lines.filter((line) => line.trim()).length;
  const treatFirstAsTitle =
    visibleLineCount > 2 &&
    firstNonEmptyLine.length >= 6 &&
    firstNonEmptyLine.length <= 34 &&
    !/[。！？!?]/.test(firstNonEmptyLine);
  let paragraphBuffer: string[] = [];
  let listBuffer: string[] = [];
  let listOrdered = false;

  const flushParagraph = () => {
    if (!paragraphBuffer.length) return;
    blocks.push({ type: 'paragraph', text: paragraphBuffer.join(' ').trim() });
    paragraphBuffer = [];
  };

  const flushList = () => {
    if (!listBuffer.length) return;
    blocks.push({ type: 'list', items: [...listBuffer], ordered: listOrdered });
    listBuffer = [];
    listOrdered = false;
  };

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index].trim();
    if (!line) {
      flushParagraph();
      flushList();
      continue;
    }
    // R8.14: markdown 表格识别（连续 | ... | 行聚合为 table block）
    if (isTableRow(line)) {
      flushParagraph();
      flushList();
      // 向前 lookahead 看连续 table rows
      const tableRows: string[] = [line];
      let cursor = index + 1;
      while (cursor < lines.length) {
        const candidate = lines[cursor].trim();
        if (isTableRow(candidate)) {
          tableRows.push(candidate);
          cursor += 1;
        } else if (!candidate) {
          // 表格行间偶有空行也容忍（前端再次防御 GFM 严格性）
          const next = lines.slice(cursor + 1).find((l) => l.trim());
          if (next && isTableRow(next.trim())) {
            cursor += 1; // 跳过空行
            continue;
          }
          break;
        } else {
          break;
        }
      }
      index = cursor - 1; // 把循环游标推进到最后一个 table row
      // 至少要有 2 行（含 header）才算表格；否则当 paragraph 处理
      if (tableRows.length >= 2) {
        // 第一行作为 header；第二行如果是分隔行就跳过；其余作为 data rows
        const header = splitTableRow(tableRows[0]);
        const dataStart = isTableSeparatorRow(tableRows[1]) ? 2 : 1;
        const rows = tableRows.slice(dataStart).map((row) => splitTableRow(row));
        blocks.push({ type: 'table', header, rows });
        continue;
      } else {
        // 退化为 paragraph
        paragraphBuffer.push(tableRows[0]);
        continue;
      }
    }
    if (index === firstNonEmptyIndex && treatFirstAsTitle) {
      blocks.push({ type: 'title', text: line.replace(/^#{1,6}\s*/, '') });
      continue;
    }
    const nextNonEmptyLine = lines.slice(index + 1).find((candidate) => candidate.trim())?.trim() || '';
    const previousLine = index > 0 ? lines[index - 1].trim() : '';
    const looksLikeOrderedHeading =
      /^\d+\.\s+/.test(line) &&
      line.length <= 42 &&
      !/[：:]$/.test(line) &&
      !/^(\d+\.\s+|[-*•]\s+)/.test(nextNonEmptyLine);
    const looksLikePlainHeading =
      line.length >= 4 &&
      line.length <= 22 &&
      !/[。！？!?：:]$/.test(line) &&
      !/^(\d+\.\s+|[-*•]\s+|#{1,6}\s+)/.test(line) &&
      !previousLine &&
      Boolean(nextNonEmptyLine) &&
      !/^(\d+\.\s+|[-*•]\s+)/.test(nextNonEmptyLine);
    const looksLikeSubheading =
      /^[^\n]{2,24}[：:]$/.test(line) &&
      /^(\d+\.\s+|[-*•]\s+)/.test(nextNonEmptyLine);
    if (/^#{1,6}\s+/.test(line) || /^[一二三四五六七八九十]+、/.test(line) || /^第[一二三四五六七八九十0-9]+部分/.test(line) || looksLikeOrderedHeading || looksLikePlainHeading) {
      flushParagraph();
      flushList();
      blocks.push({ type: 'heading', text: line.replace(/^#{1,6}\s*/, '') });
      continue;
    }
    if (looksLikeSubheading) {
      flushParagraph();
      flushList();
      blocks.push({ type: 'subheading', text: line });
      continue;
    }
    const unorderedMatch = line.match(/^[-*•]\s+(.+)$/);
    const orderedMatch = line.match(/^\d+\.\s+(.+)$/);
    if (unorderedMatch || orderedMatch) {
      flushParagraph();
      const nextOrdered = Boolean(orderedMatch);
      const itemText = (orderedMatch || unorderedMatch)?.[1].trim() || line;
      if (listBuffer.length && listOrdered !== nextOrdered) {
        flushList();
      }
      listOrdered = nextOrdered;
      listBuffer.push(itemText);
      continue;
    }
    paragraphBuffer.push(line);
  }

  flushParagraph();
  flushList();
  return blocks;
}

function AnswerDocument({ text }: { text: string }) {
  const blocks = useMemo(() => parseAnswerBlocks(text), [text]);
  if (!blocks.length) return null;
  const leadParagraphIndex = blocks.findIndex((block, index) => {
    if (block.type !== 'paragraph') return false;
    return blocks.slice(0, index).every((item) => item.type === 'title');
  });
  return (
    <div className="space-y-4 text-[#2c315d]">
      {blocks.map((block, index) => {
        if (block.type === 'title') {
          return (
            <div key={`title-${index}`} className="space-y-2">
              <h1 className="text-[22px] xl:text-[24px] font-semibold tracking-[-0.02em] text-[#1f275b] leading-[1.3]">
                {renderInlineEmphasis(block.text)}
              </h1>
              <div className="h-px w-16 bg-[#d8defb]" />
            </div>
          );
        }
        if (block.type === 'heading') {
          return (
            <h2 key={`heading-${index}`} className="pt-2 text-[19px] xl:text-[20px] font-semibold text-[#25306a] leading-[1.5] tracking-[-0.01em]">
              {renderInlineEmphasis(block.text)}
            </h2>
          );
        }
        if (block.type === 'subheading') {
          return (
            <h3 key={`subheading-${index}`} className="pt-1 text-[15px] xl:text-[15.5px] font-semibold text-[#2a356f] leading-7">
              {renderInlineEmphasis(block.text)}
            </h3>
          );
        }
        if (block.type === 'list') {
          const ListTag = block.ordered ? 'ol' : 'ul';
          return (
            <ListTag
              key={`list-${index}`}
              className={`${block.ordered ? 'list-decimal' : 'list-disc'} pl-6 space-y-2 text-[14.5px] xl:text-[15px] leading-7 text-[#2f376d] marker:text-[#4b63df]`}
            >
              {block.items.map((item, itemIndex) => (
                <li key={`list-item-${index}-${itemIndex}`} className="pl-1">{renderInlineEmphasis(item)}</li>
              ))}
            </ListTag>
          );
        }
        if (block.type === 'table') {
          // R8.14: markdown 表格渲染
          return (
            <div key={`table-${index}`} className="overflow-x-auto rounded-xl border border-[#d8defb] bg-white">
              <table className="w-full text-[13px] xl:text-[14px]">
                <thead>
                  <tr className="bg-[#f3f5fc]">
                    {block.header.map((cell, cellIndex) => (
                      <th
                        key={`th-${index}-${cellIndex}`}
                        className="px-3 py-2 text-left font-semibold text-[#1f275b] border-b border-[#d8defb] whitespace-nowrap"
                      >
                        {renderInlineEmphasis(cell)}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {block.rows.map((row, rowIndex) => (
                    <tr
                      key={`tr-${index}-${rowIndex}`}
                      className={rowIndex % 2 === 0 ? 'bg-white' : 'bg-[#fafbff]'}
                    >
                      {row.map((cell, cellIndex) => (
                        <td
                          key={`td-${index}-${rowIndex}-${cellIndex}`}
                          className="px-3 py-2 text-[#30376b] border-b border-[#eef0f9] align-top leading-6"
                        >
                          {renderInlineEmphasis(cell)}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        }
        const isLead = index === leadParagraphIndex;
        return (
          <p
            key={`paragraph-${index}`}
            className={isLead
              ? 'text-[15px] xl:text-[15.5px] leading-8 text-[#24305f] font-medium'
              : 'text-[14.5px] xl:text-[15px] leading-7 text-[#30376b]'}
          >
            {renderInlineEmphasis(block.text)}
	          </p>
	        );
	      })}
	    </div>
  );
}

/**
 * 给 AnswerDocument 套一层"打字机"效果：
 * - streaming=true：用 useTypewriter 把 text 一段段蹦出来（30ms 推进 2 字符）
 * - streaming=false：直接显示完整 text（历史消息 / 完成态）
 */
function StreamingAnswerDocument({ text, streaming }: { text: string; streaming: boolean }) {
  const displayed = useTypewriter(text, { enabled: streaming, charsPerTick: 2, tickMs: 30 });
  return <AnswerDocument text={displayed} />;
}

// R4 P0-5 fix (B 5/23 16:46 钦定) · 4 个新 badge / card
// 待澄清徽章 / 待审批徽章 / 文件身份 badge / 合同结构卡片

/**
 * 顾源源 5/25 真用反馈: AI 同事执行进度从 modal 抬到 sidebar 系统状态正上方.
 * 进度条 + 灰色小字"庆华正在做: ...". 完成 (success/failed/partial) 后保留 30s 再 fade.
 * 自身轮询 getBotTaskPlanProgress, 终态自动停, 不阻塞用户.
 */
function PlanProgressMini({
  planId,
  botName,
  onDismiss,
}: {
  planId: string;
  botName: string;
  onDismiss: () => void;
}) {
  const [progress, setProgress] = useState<PlanProgressRecord | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    let timer: number | null = null;
    let fadeTimer: number | null = null;

    const isTerminal = (s: string) => s === 'success' || s === 'failed' || s === 'partial';

    const tick = async () => {
      if (cancelled) return;
      try {
        const r = await getBotTaskPlanProgress(planId);
        if (cancelled) return;
        setProgress(r);
        setError(null);
        if (isTerminal(r.execution_status)) {
          // 完成后保留 30s 让用户看到, 然后自动 fade
          fadeTimer = window.setTimeout(() => {
            if (!cancelled) onDismiss();
          }, 30_000);
          return;
        }
      } catch (e) {
        if (!cancelled) setError(e instanceof Error ? e.message : '查询进度失败');
      }
      timer = window.setTimeout(tick, 2000);
    };
    void tick();

    return () => {
      cancelled = true;
      if (timer) window.clearTimeout(timer);
      if (fadeTimer) window.clearTimeout(fadeTimer);
    };
  }, [planId, onDismiss]);

  const exec = progress?.execution_status;
  const pct = progress?.progress.percent ?? 0;
  const completed = progress?.progress.completed ?? 0;
  const total = progress?.progress.total ?? 0;
  const current = progress?.progress.current || '准备中';

  const isSuccess = exec === 'success';
  const isFailed = exec === 'failed' || exec === 'partial';
  const isRunning = exec === 'running' || exec === 'pending_execute' || exec === 'not_started' || !exec;

  const barColor = isSuccess
    ? 'bg-emerald-500'
    : isFailed
      ? 'bg-amber-500'
      : 'bg-[#5B7BFE]';
  const statusLabel = isSuccess
    ? `✓ ${botName} 完成`
    : isFailed
      ? `${exec === 'partial' ? '⚠' : '✗'} ${botName} ${exec === 'partial' ? '部分完成' : '失败'}`
      : `${botName} 正在执行`;

  return (
    <div className="mx-2 mb-2 rounded-lg border border-gray-200 bg-white px-2.5 py-2 shadow-sm">
      <div className="flex items-center justify-between gap-1 mb-1">
        <div className="text-[10.5px] font-medium text-gray-700 truncate">{statusLabel}</div>
        <button
          type="button"
          onClick={onDismiss}
          className="shrink-0 text-[9px] text-gray-400 hover:text-gray-700 px-1"
          title="关闭进度提示 (任务继续执行)"
        >
          ✕
        </button>
      </div>
      {/* 进度条 */}
      <div className="h-1 w-full rounded-full bg-gray-100 overflow-hidden">
        <div
          className={`h-full ${barColor} transition-all duration-300`}
          style={{ width: `${Math.max(0, Math.min(100, pct))}%` }}
        />
      </div>
      {/* 灰色小字 — 正在做什么 + 第几步 */}
      <div className="mt-1 flex items-center gap-1.5 text-[9.5px] text-gray-500 leading-tight">
        <span className="font-mono text-gray-400">{completed}/{total}</span>
        <span className="truncate">
          {isRunning ? `正在: ${current}` : isSuccess ? '全部完成, 30s 后收起' : `${current} · 见详情`}
        </span>
      </div>
      {error && (
        <div className="mt-1 text-[9.5px] text-red-600 truncate" title={error}>
          ⚠ {error}
        </div>
      )}
    </div>
  );
}

