  useEffect(() => {
    if (!clientEditorModalState.open) return undefined;
    const detail = clientEditorModalState.editingClientId ? `editing:${clientEditorModalState.editingClientId}` : 'creating';
    reportWorkspaceInteractionState(true, 'client_modal', detail);
    return () => {
      reportWorkspaceInteractionState(false, 'client_modal', detail);
    };
  }, [clientEditorModalState.editingClientId, clientEditorModalState.open, reportWorkspaceInteractionState]);

  const openCloudAuthModal = (
    action: 'login' | 'join' | 'create' = 'join',
    seed: {
      cloudApiUrl?: string;
      inviteCode?: string;
      organizationName?: string;
      clearRememberedAccount?: boolean;
    } = {},
  ) => {
    const rememberedCloudAccount =
      !seed.clearRememberedAccount && (localInputMemoryState.cloudAuth.lastEmail
        ? localInputMemoryState.cloudAuth.accounts.find((account) => account.email === localInputMemoryState.cloudAuth.lastEmail)
        : null)
      || (!seed.clearRememberedAccount ? localInputMemoryState.cloudAuth.accounts[0] : null)
      || null;
    const rememberedIdentifier = rememberedCloudAccount?.identifier || rememberedCloudAccount?.email || '';
    const defaultEmail = seed.clearRememberedAccount ? '' : (currentSessionUser?.email || rememberedCloudAccount?.email || '');
    const defaultPhone = seed.clearRememberedAccount ? '' : (currentSessionUser?.phone || '');
    const defaultFullName = seed.clearRememberedAccount
      ? ''
      : sanitizePersonNameInput(currentSessionUser?.fullName || rememberedCloudAccount?.fullName || '');
    const defaultCloudApiUrl = seed.cloudApiUrl || activeWorkspaceRecord?.cloudApiUrl || settingsState?.cloudApiUrl || '';
    setCloudAuthAction(action);
    setCloudAuthMessage('');
    setCloudAuthShowPassword(false);
    setCloudAuthInviteStatus({ code: '', loading: false, valid: null, message: '' });
    setOrganizationSelection(null);
    setCloudAuthForm({
      cloudApiUrl: defaultCloudApiUrl,
      organizationName: seed.organizationName || '',
      email: defaultEmail,
      identifier: rememberedIdentifier || defaultEmail || defaultPhone,
      phone: defaultPhone,
      fullName: defaultFullName,
      password: rememberedCloudAccount?.password || '',
      confirmPassword: rememberedCloudAccount?.password || '',
      inviteCode: seed.inviteCode || '',
      departmentId: '',
      jobTitle: '',
      managerName: '',
      currentFocus: '',
      rememberMe: true,
      rememberInputs: localInputMemoryState.cloudAuth.rememberInputs,
    });
    setCloudAuthModalOpen(true);
  };

  const resetFeishuWorkspaceTransientState = () => {
    feishuStatusHydrationInFlightRef.current = false;
    feishuTaskSyncReadinessInFlightRef.current = false;
    setOrgFeishuIntegrationState(DEFAULT_ORG_FEISHU_INTEGRATION);
    setFeishuDeliveryProfileState(DEFAULT_FEISHU_DELIVERY_PROFILE);
    setFeishuMemberAuthorizationState(DEFAULT_FEISHU_MEMBER_AUTHORIZATION);
    setFeishuTaskSyncReadiness(DEFAULT_FEISHU_TASK_SYNC_READINESS);
    setOrgFeishuIntegrationLoaded(false);
    setFeishuDeliveryProfileLoaded(false);
    setFeishuMemberAuthorizationLoaded(false);
    setFeishuAuthorizationFlowState(null);
    setFeishuAuthorizationBusyAction('idle');
    setIsFeishuImportOpen(false);
    setFeishuImportStatus(null);
    setFeishuImportQuery('');
    setFeishuImportLinksText('');
    setFeishuImportCandidates([]);
    setSelectedFeishuImportKeys([]);
    setIsFeishuImportLoading(false);
    setIsFeishuImportSubmitting(false);
    setFeishuImportResult(null);
    setFeishuImportMessage('');
  };

  const resetBusinessWorkspaceTransientState = () => {
    // 先作废组织计划的在途请求，再清理界面。新 sandbox 的加载会取得更大的
    // request id；旧空间迟到回包不能重新写回当前界面。
    organizationPlanningRequestRef.current += 1;
    organizationPlanningCacheRef.current = { scopeKey: '', loadedAt: 0 };
    optimisticTasksRef.current.clear();
    taskMutationOverlaysRef.current.clear();
    reviewDirtyTaskIdsRef.current.clear();
    reviewDraftRevisionRef.current = {};
    reviewLoadAbortControllerRef.current?.abort();
    reviewLoadAbortControllerRef.current = null;
    reviewLoadSequenceRef.current += 1;
    weeklyOverviewRefreshRequestRef.current = '';
    if (weeklyOverviewRefreshPollRef.current !== null) {
      window.clearTimeout(weeklyOverviewRefreshPollRef.current);
      weeklyOverviewRefreshPollRef.current = null;
    }
    workspaceStartMessageAbortControllerRef.current?.abort();
    workspaceStartMessageAbortControllerRef.current = null;
    workspaceComposerDraftRef.current = {};
    workspaceComposerFocusRef.current = {
      key: '',
      focused: false,
      selectionStart: null,
      selectionEnd: null,
      updatedAt: 0,
    };
    activeWorkingDocumentsClientRef.current = '';
    dispatchWorkspaceClientUi({ type: 'resetAll' });
    setClients([]);
    setCurrentClientId('');
    setWorkspace(null);
    setWorkspacePageContext(null);
    setWorkspacePageContextError(null);
    setWorkspacePersistedProposalDrafts([]);
    setWorkspacePersistedProposalDraftsError(null);
    setWorkspacePersistedProposalDraftsBusyId(null);
    setWorkspacePersistedProposalDraftsLoading(false);
    setTasks([]);
    setCustomerMeetings([]);
    setTaskLists([]);
    setTaskTags([]);
    setUpdatingTaskStatusIds([]);
    setExpandedTaskIds([]);
    setProposals([]);
    setActiveSupportRequest(null);
    setSupportRequestActionBusy(false);
    setSupportRequestResolutionNote('');
    setIsImportSubmitting(false);
    setLatestImportFeedback(null);
    setActiveWorkingDocuments([]);
    setClientWorkspaceSurfaceModeRequest(null);
    setTaskSettingsState(null);
    setOrgAiRuntimeStatus(null);
    setReviewDashboard(null);
    setWeeklyOverviewRefreshStatus(null);
    setReviewHistory([]);
    setIsLoadingReviewHistory(false);
    setReviewDirtyTaskIds([]);
    setRadars([]);
    setCandidates([]);
    setIntelligenceProfiles([]);
    setHandbookEntries([]);
    setGrowthContextJump(null);
    setTaskEvidencePreview(null);
    setTaskEvidenceError(null);
    setIsTaskEvidenceLoading(false);
    setCockpitEvidenceSnapshot(null);
    setCockpitEvidenceError(null);
    setIsCockpitEvidenceLoading(false);
    setEvidenceMode(null);
    setEvidenceTaskId(null);
    setEvidenceClientId(null);
    // Week selection is a presentation cursor, not sandbox-owned business data.
    // Generic bootstrap/workspace cache refreshes must not move it back to the
    // current week while a user-triggered week request is still in flight.
    setDepartmentOptions([]);
    setStrictPlanningCycles([]);
    setStrictDecisionActions([]);
    setIsOrganizationPlanningLoading(true);
    setOrganizationPlanningLoadError('');
    setEmployeeReviews([]);
    setEmployeeDirectoryStatus('idle');
    setEmployeeDirectoryError('');
    setOrgModelState(EMPTY_ORG_MODEL_SETTINGS);
    setOrgMembershipState(DEFAULT_ORG_MEMBERSHIP_SUMMARY);
    setOrgAdminClaimStatus(DEFAULT_ORG_ADMIN_CLAIM_STATUS);
    setAgentWorklogs([]);
    setAgentWeeklyDigests([]);
    setAgentWeeklyPlans([]);
    setLogs([]);
    setClientWorkspaceSettingsState(DEFAULT_CLIENT_WORKSPACE_SETTINGS);
    setTopicsSettingsState(DEFAULT_TOPICS_SETTINGS);
    setHandbookSettingsState(DEFAULT_HANDBOOK_SETTINGS);
    setSystemAdminSettingsState(DEFAULT_SYSTEM_ADMIN_SETTINGS);
    setMaintenanceModeStatus(null);
    setMaintenanceModeError(null);
    setIsMaintenanceModeLoading(false);
    setMaintenanceModeBusyAction(null);
    setSettingsSectionLoaded({
      overview: false,
      account: false,
      tasks: false,
      client_workspace: false,
      topics: false,
      handbook: false,
      system_admin: false,
      org_overview: false,
      org_departments: false,
      org_people: false,
      org_rules: false,
      system_logs: false,
      about: false,
    });
    setClientWorkspaceInlineEditor(null);
    setWorkspaceSelectedMeetingId('');
    setWorkspaceMeetingTranscript('');
    setWorkspaceMeetingNotes('');
    setClientEditorModalState({
      open: false,
      origin: 'default',
      editingClientId: null,
      requestId: `workspace-reset-${Date.now()}`,
      initialDraft: createEmptyClientEditorDraft(),
    });
    setBusinessWorkspaceResetKey((value) => value + 1);
  };

  const refreshWorkspaceAwareState = async (
    nextWorkspaces?: SandboxWorkspacesResponse,
    transitionToken?: WorkspaceTransitionToken,
  ) => {
    const ownsTransition = !transitionToken;
    const token = transitionToken || beginWorkspaceTransition('switching', '正在刷新当前工作空间…', {
      sandboxId: nextWorkspaces?.activeSandboxId || activeSandboxIdRef.current || workspacesState?.activeSandboxId || '',
      reason: 'refresh-workspace-aware-state',
    });
    try {
    if (nextWorkspaces && shouldApplyWorkspaceLoad(token)) {
      setWorkspacesState(nextWorkspaces);
      activeSandboxIdRef.current = nextWorkspaces.activeSandboxId || '';
      pinWorkspaceTransitionSandbox(token, nextWorkspaces.activeSandboxId);
    }
    const nextActiveWorkspace = nextWorkspaces
      ? nextWorkspaces.workspaces.find((item) => item.id === nextWorkspaces.activeSandboxId) || null
      : activeWorkspaceRecord;
    pinWorkspaceTransitionSandbox(token, nextActiveWorkspace?.id || nextWorkspaces?.activeSandboxId || null);
    if (!shouldApplyWorkspaceLoad(token)) return;
    markWorkspaceRuntime('switching', `正在清理 ${nextActiveWorkspace?.name || '目标'} 工作空间缓存…`);
    resetFeishuWorkspaceTransientState();
    resetBusinessWorkspaceTransientState();
    markWorkspaceRuntime('verifying', `正在验证 ${nextActiveWorkspace?.name || '目标'} 工作空间身份…`);
    const rawAuth = await loadAuthBlock({ transition: token });
    if (!shouldApplyWorkspaceLoad(token)) return;
    const nextAuth = await recoverIncompleteAuthBlock(rawAuth, { transition: token });
    if (!shouldApplyWorkspaceLoad(token)) return;
    const nextRuntime = resolveWorkspaceRuntimeFromRecord(nextActiveWorkspace, nextAuth);
    if (nextRuntime.status === 'needs_login' || nextRuntime.status === 'identity_error') {
      if (shouldApplyWorkspaceLoad(token)) markWorkspaceRuntime(nextRuntime.status, nextRuntime.message);
      return;
    }
    if (nextRuntime.status === 'local_draft') {
      await Promise.all([
        loadSettingsBlock({ applyRuntime: false, transition: token }),
        loadLocalInputMemoryBlock({ transition: token }),
        refreshMaintenanceModeStatus({ silent: true, workspace: nextActiveWorkspace }),
      ]);
      if (!shouldApplyWorkspaceLoad(token)) return;
      if (shouldApplyWorkspaceLoad(token)) markWorkspaceRuntime('local_draft', nextRuntime.message);
      return;
    } else {
      markWorkspaceRuntime('switching', `正在加载 ${nextActiveWorkspace?.name || '目标'} 工作空间数据…`);
    }
    await Promise.all([
      loadSettingsBlock({ applyRuntime: false, transition: token }),
      loadLocalInputMemoryBlock({ transition: token }),
      refreshMaintenanceModeStatus({ silent: true, workspace: nextActiveWorkspace }),
    ]);
    if (!shouldApplyWorkspaceLoad(token)) return;
    markWorkspaceRuntime('switching', `正在同步 ${nextActiveWorkspace?.name || '目标'} 的组织 AI 配置…`);
    const aiRuntime = await loadOrgAiRuntimeBlock({ sync: true, transition: token, timeoutMs: 15000 }).catch(() => null);
    if (!aiRuntime && shouldApplyWorkspaceLoad(token)) {
      await loadOrgAiRuntimeBlock({ transition: token }).catch(() => null);
    }
    if (!shouldApplyWorkspaceLoad(token)) return;
    markWorkspaceRuntime('switching', `正在同步 ${nextActiveWorkspace?.name || '目标'} 的成员、部门和清单…`);
    await Promise.all([
      loadOrgMembershipBlock({ transition: token }).catch(() => DEFAULT_ORG_MEMBERSHIP_SUMMARY),
      loadOrgAdminClaimStatusBlock(nextAuth.sessionMode === 'cloud', { transition: token }).catch(() => DEFAULT_ORG_ADMIN_CLAIM_STATUS),
      loadOrgFeishuIntegrationBlock({ transition: token }).catch(() => DEFAULT_ORG_FEISHU_INTEGRATION),
      loadFeishuDeliveryProfileBlock({ transition: token }).catch(() => DEFAULT_FEISHU_DELIVERY_PROFILE),
      loadFeishuMemberAuthorizationBlock({ transition: token }).catch(() => DEFAULT_FEISHU_MEMBER_AUTHORIZATION),
    ]);
    if (!shouldApplyWorkspaceLoad(token)) return;
    markWorkspaceRuntime('switching', `正在检查 ${nextActiveWorkspace?.name || '目标'} 的本地任务镜像…`);
    await repairCurrentWorkspaceTaskMirrors().catch((error) => {
      console.warn('[task-mirror-repair] deferred during workspace refresh', {
        sandboxId: token.sandboxId,
        reason: error instanceof Error ? error.message : String(error),
      });
      return null;
    });
    if (!shouldApplyWorkspaceLoad(token)) return;
    markWorkspaceRuntime('switching', `正在加载 ${nextActiveWorkspace?.name || '目标'} 的客户、任务、事件线和设置…`);
    await Promise.all([
      loadClientWorkspaceSettingsBlock({ transition: token }).catch(() => undefined),
      loadTopicsSettingsBlock({ transition: token }).catch(() => undefined),
      loadHandbookSettingsBlock({ transition: token }).catch(() => undefined),
      nextAuth.user?.primaryRole === 'admin'
        ? loadSystemAdminSettingsBlock(nextAuth.sessionMode === 'cloud', { transition: token }).catch(() => undefined)
        : loadOrgModelBlock({ transition: token }).catch(() => undefined),
      loadClientBlock(undefined, {
        transition: token,
        organizationId: nextAuth.user?.organizationId,
      }).catch(() => undefined),
      loadTaskSettingsBlock({ transition: token }).catch(() => undefined),
      loadTaskBlock({ transition: token }).catch(() => undefined),
      loadOrganizationPlanningBlock({
        transition: token,
        organizationId: nextAuth.user?.organizationId,
      }).catch(() => undefined),
      (async () => {
        const loader = loadEventLinesForWorkspaceRef.current;
        if (!loader) {
          console.warn('[event-lines] loader not ready during workspace refresh', {
            sandboxId: token.sandboxId,
            reason: token.reason,
          });
          throw new Error('事件线加载器尚未就绪');
        }
        await loader({ transition: token, resetFilter: true });
      })().catch(() => undefined),
      loadTopicsBlock({ transition: token }).catch(() => undefined),
      loadHandbookBlock({ transition: token }).catch(() => undefined),
      loadReviewBlock(resolveSelectedReviewWeekLabel(), {
        skipAi: true,
        perspective: resolveDefaultReviewPerspectiveForUser(nextAuth.user || null),
        departmentId: resolveDefaultReviewDepartmentIdForUser(
          nextAuth.user || null,
          resolveDefaultReviewPerspectiveForUser(nextAuth.user || null),
        ),
        transition: token,
      }).catch(() => undefined),
      loadReviewHistoryBlock({ transition: token }).catch(() => undefined),
      nextAuth.user?.primaryRole === 'admin'
        ? loadEmployeeReviewBlock({ quiet: true, transition: token }).catch(() => undefined)
        : Promise.resolve(undefined),
    ]);
      if (shouldApplyWorkspaceLoad(token)) applyWorkspaceRuntime(nextActiveWorkspace, nextAuth);
    } finally {
      if (ownsTransition && shouldApplyWorkspaceLoad(token)) {
        await waitForWorkspaceTransitionMinimum();
        markLoadingPhase('启动完成');
        setLoading(false);
        setLoadingSubProgress(0);
        setWorkspaceTransitionSlow(false);
      }
    }
  };

  const handleActivateWorkspace = async (workspaceId: string) => {
    if (pendingTaskSaveCountRef.current > 0 || pendingTaskSaveCount > 0) {
      flash('info', '任务正在保存，请稍候几秒再切换工作空间。');
      return;
    }
    const targetWorkspace = (workspacesState?.workspaces || []).find((item) => item.id === workspaceId) || null;
    const targetNeedsLogin = Boolean(
      targetWorkspace?.requiresLogin
      || targetWorkspace?.cloudNeedsLogin
      || targetWorkspace?.cloudConnectionStatus === 'needs_login'
      || targetWorkspace?.runtimeStatus === 'needs_login',
    );
    if (targetWorkspace?.kind === 'organization' && targetNeedsLogin) {
      setWorkspaceManagerOpen(false);
      openCloudAuthModal('login', {
        cloudApiUrl: targetWorkspace.cloudApiUrl,
        organizationName: targetWorkspace.organizationName || targetWorkspace.name,
      });
      setCloudAuthMessage(`${targetWorkspace.name} 的本机会话已失效，请重新登录该组织。`);
      return;
    }
    setWorkspaceManagerBusy(true);
    const previousSandboxId = currentActiveSandboxId();
    const transitionToken = beginWorkspaceTransition('switching', `正在切换到 ${targetWorkspace?.name || '目标'} 工作空间…`, {
      sandboxId: workspaceId,
      reason: 'activate-workspace',
    });
    activeSandboxIdRef.current = workspaceId;
    resetFeishuWorkspaceTransientState();
    resetBusinessWorkspaceTransientState();
    try {
      const response = await activateWorkspace(workspaceId, transitionToken.id);
      if (response.activeSandboxId !== workspaceId) {
        throw new ApiRequestError(409, 'workspace_switch_identity_mismatch', '目标工作空间身份校验不一致');
      }
      pinWorkspaceTransitionSandbox(transitionToken, response.activeSandboxId || workspaceId);
      await refreshWorkspaceAwareState(response, transitionToken);
      if (shouldApplyWorkspaceLoad(transitionToken)) {
        setWorkspaceManagerOpen(false);
        flash('success', '已切换工作空间。客户、任务和文档已按当前工作空间刷新显示。');
      }
    } catch (error) {
      activeSandboxIdRef.current = previousSandboxId;
      setWorkspaceRequestContext(previousSandboxId, transitionToken.id);
      const currentWorkspace = (workspacesState?.workspaces || []).find((item) => item.id === workspacesState?.activeSandboxId) || null;
      if (shouldApplyWorkspaceLoad(transitionToken)) {
        applyWorkspaceRuntime(currentWorkspace, authState);
        if (
          targetWorkspace?.kind === 'organization'
          && error instanceof ApiRequestError
          && [
            'needs_login',
            'workspace_session_missing',
            'workspace_secret_missing',
            'workspace_secret_invalid',
          ].includes(error.code)
        ) {
          setWorkspaceManagerOpen(false);
          openCloudAuthModal('login', {
            cloudApiUrl: targetWorkspace.cloudApiUrl,
            organizationName: targetWorkspace.organizationName || targetWorkspace.name,
          });
          setCloudAuthMessage(`${targetWorkspace.name} 缺少可用的本机登录信息，请重新登录。`);
          void getWorkspaces()
            .then((nextWorkspaces) => {
              if (shouldApplyWorkspaceLoad(transitionToken)) {
                setWorkspacesState(nextWorkspaces);
              }
            })
            .catch(() => undefined);
        } else {
          flash('error', error instanceof Error ? error.message : '切换工作空间失败');
        }
      }
    } finally {
      if (shouldApplyWorkspaceLoad(transitionToken)) {
        await waitForWorkspaceTransitionMinimum();
        setWorkspaceManagerBusy(false);
        markLoadingPhase('启动完成');
        setLoading(false);
      }
    }
  };

  const activeWorkspaceMatchesCloudUrl = (cloudApiUrl: string) => {
    if (!cloudApiUrl || !activeWorkspaceRecord?.cloudConnected) return false;
    return normalizeUrlForComparison(activeWorkspaceRecord.cloudApiUrl) === normalizeUrlForComparison(cloudApiUrl);
  };

  const handleSelectOrganization = async (organizationId: string) => {
    if (!organizationSelection?.token) return;
    setCloudAuthSubmitting(true);
    setCloudAuthMessage('');
    try {
      const response = await selectOrganization({
        organizationSelectionToken: organizationSelection.token,
        organizationId,
        cloudApiUrl: cloudApiUrlFromHost(cloudAuthForm.cloudApiUrl),
      });
      setAuthState(response);
      setOrganizationSelection(null);
      const authenticatedWorkspaces = await getWorkspaces();
      await refreshWorkspaceAwareState(authenticatedWorkspaces);
      setCloudAuthModalOpen(false);
      flash('success', '已进入所选组织工作空间。');
    } catch (error) {
      setCloudAuthMessage(error instanceof Error ? error.message : '选择组织失败');
    } finally {
      setCloudAuthSubmitting(false);
    }
  };

  useEffect(() => {
    if (cloudAuthAction !== 'join') return undefined;
    const code = normalizeDepartmentInviteInput(cloudAuthForm.inviteCode);
    if (!code) {
      setCloudAuthInviteStatus({ code: '', loading: false, valid: null, message: '' });
      return undefined;
    }
    const typedCloudUrl = cloudApiUrlFromHost(cloudAuthForm.cloudApiUrl);
    if (!typedCloudUrl) {
      setCloudAuthInviteStatus({
        code,
        loading: false,
        valid: null,
        message: '填写组织云端地址后，提交时会连接云端识别邀请码。',
      });
      return undefined;
    }
    let cancelled = false;
    setCloudAuthInviteStatus({ code, loading: true, valid: null, message: '正在识别邀请码...' });
    const timer = window.setTimeout(() => {
      void resolveInviteCode(code, typedCloudUrl)
        .then((result) => {
          if (cancelled) return;
          setCloudAuthInviteStatus({
            code,
            loading: false,
            valid: result.valid,
            message: result.message || (result.valid ? '邀请码已识别' : '邀请码无效'),
          });
          if (result.valid && result.departmentId) {
            setCloudAuthForm((prev) => normalizeDepartmentInviteInput(prev.inviteCode) === code ? { ...prev, departmentId: result.departmentId || prev.departmentId } : prev);
          }
          if (result.valid && result.organizationId) {
            void loadDepartmentOptionsBlock(result.organizationId, typedCloudUrl).catch(() => undefined);
          }
        })
        .catch((error) => {
          if (cancelled) return;
          setCloudAuthInviteStatus({
            code,
            loading: false,
            valid: false,
            message: error instanceof Error ? error.message : '邀请码识别失败',
          });
        });
    }, 400);
    return () => {
      cancelled = true;
      window.clearTimeout(timer);
    };
  }, [cloudAuthAction, cloudAuthForm.cloudApiUrl, cloudAuthForm.inviteCode, settingsState?.cloudApiUrl]);

  useEffect(() => {
    if (settingsState) {
      setDraft((prev) => ({
        ...prev,
        currentOperatorId: settingsState.currentOperatorId,
        cloudApiUrl: settingsState.cloudApiUrl || '',
        aiProvider: settingsState.aiProvider === 'mock' ? 'openai_compatible' : settingsState.aiProvider,
        aiProviderLabel: settingsState.aiProvider === 'mock' ? AI_CONFIG_PRESETS.custom.providerLabel : (settingsState.aiProviderLabel || ''),
        aiBaseUrl: settingsState.aiProvider === 'mock' ? '' : (settingsState.aiBaseUrl || ''),
        aiModel: settingsState.aiProvider === 'mock' ? '' : settingsState.aiModel,
        advancedAiRoutingEnabled: Boolean(settingsState.advancedAiRoutingEnabled),
        aiModelMode: settingsState.aiModelMode || 'auto',
        aiModelProfiles: normalizeAiModelProfiles(settingsState.aiModelProfiles),
      }));
    }
  }, [settingsState]);

  useEffect(() => {
    setDraft((prev) => ({
      ...prev,
      apiKey: localInputMemoryState.aiSettings.rememberApiKey ? localInputMemoryState.aiSettings.apiKey : '',
    }));
    setRememberAiInputKey(localInputMemoryState.aiSettings.rememberApiKey);
  }, [localInputMemoryState.aiSettings.apiKey, localInputMemoryState.aiSettings.rememberApiKey]);

  useEffect(() => {
    setTaskSettingsDraft(effectiveTaskSettings);
  }, [effectiveTaskSettings]);

  useEffect(() => {
    setTopicsDraft(topicsSettingsState);
  }, [topicsSettingsState]);

  useEffect(() => {
    setHandbookDraft({
      ...handbookSettingsState,
      defaultTagsText: handbookSettingsState.defaultTags.join(', '),
    });
  }, [handbookSettingsState]);

  useEffect(() => {
    setSystemAdminDraft(systemAdminSettingsState);
  }, [systemAdminSettingsState]);

  useEffect(() => {
    if (isOrgModelDraftDirty || isSavingOrgModel) return;
    setOrgModelDraft(orgModelState);
  }, [isOrgModelDraftDirty, isSavingOrgModel, orgModelState]);

  const getOrgSetupInputDrafts = useCallback(() => orgSetupInputDraftsRef.current, []);

  const setOrgSetupInputDrafts = useCallback((next: OrganizationSetupInputDraftState) => {
    orgSetupInputDraftsRef.current = next;
  }, []);

  const clearOrgSetupInputDrafts = useCallback(() => {
    orgSetupInputDraftsRef.current = {};
  }, []);

  useEffect(() => {
    setProfileDraft({
      fullName: currentSessionUser?.fullName || '',
      email: currentSessionUser?.email || '',
      phone: currentSessionUser?.phone || '',
    });
    setProfileMessage('');
  }, [currentSessionUser?.email, currentSessionUser?.fullName, currentSessionUser?.phone]);

  const markLoadingPhase = (phase: string) => {
    setLoadingPhase(phase);
    console.info(`[bootstrap] phase=${phase}`);
  };

  const markWorkspaceRuntime = (status: WorkspaceRuntimeStatus, message: string) => {
    workspaceRuntimeStatusRef.current = status;
    workspaceRuntimeLastMarkedAtRef.current = Date.now();
    setWorkspaceRuntimeStatus(status);
    setWorkspaceRuntimeMessage(message);
    if (WORKSPACE_BUSY_RUNTIME_STATUSES.has(status)) {
      markLoadingPhase(message);
    }
  };

  const beginWorkspaceTransition = (
    status: Extract<WorkspaceRuntimeStatus, 'verifying' | 'switching'>,
    message: string,
    options?: { sandboxId?: string | null; reason?: string },
  ): WorkspaceTransitionToken => {
    const token: WorkspaceTransitionToken = {
      id: Math.max(workspaceTransitionRef.current.id + 1, Date.now()),
      sandboxId: options?.sandboxId || activeSandboxIdRef.current || workspacesState?.activeSandboxId || '',
      reason: options?.reason || status,
    };
    workspaceTransitionRef.current = token;
    setWorkspaceRequestContext(token.sandboxId, token.id);
    workspaceTransitionStartedAtRef.current = Date.now();
    setLoading(true);
    setLoadingSubProgress(0);
    setWorkspaceTransitionSlow(false);
    markWorkspaceRuntime(status, message);
    return token;
  };

  const waitForWorkspaceTransitionMinimum = async () => {
    const elapsed = Date.now() - workspaceTransitionStartedAtRef.current;
    const remaining = Math.max(0, WORKSPACE_TRANSITION_MIN_VISIBLE_MS - elapsed);
    if (remaining <= 0) return;
    await new Promise<void>((resolve) => {
      window.setTimeout(resolve, remaining);
    });
  };

  const pinWorkspaceTransitionSandbox = (token: WorkspaceTransitionToken, sandboxId?: string | null) => {
    if (workspaceTransitionRef.current.id !== token.id) return;
    const nextToken = { ...token, sandboxId: sandboxId || '' };
    token.sandboxId = nextToken.sandboxId;
    workspaceTransitionRef.current = nextToken;
    setWorkspaceRequestContext(nextToken.sandboxId, nextToken.id);
  };

  const isWorkspaceTransitionCurrent = (token: WorkspaceTransitionToken | null | undefined): boolean => {
    if (!token) return !WORKSPACE_BUSY_RUNTIME_STATUSES.has(workspaceRuntimeStatusRef.current);
    const current = workspaceTransitionRef.current;
    if (token.id !== current.id) return false;
    if (token.sandboxId && current.sandboxId && token.sandboxId !== current.sandboxId) return false;
    return true;
  };

  const currentActiveSandboxId = () => activeSandboxIdRef.current || workspacesState?.activeSandboxId || '';

  const shouldApplyWorkspaceLoad = (token?: WorkspaceTransitionToken | null, startedSandboxId?: string): boolean => {
    if (!isWorkspaceTransitionCurrent(token)) return false;
    if (token) return true;
    const currentSandboxId = currentActiveSandboxId();
    return !startedSandboxId || !currentSandboxId || startedSandboxId === currentSandboxId;
  };

  const eventLineWorkspaceKey = workspacesState?.activeSandboxId || 'local';
  const [eventLineStatesBySandbox, setEventLineStatesBySandbox] = useState<Record<string, EventLineWorkspaceState>>({});
  const eventLineStatesBySandboxRef = useRef<Record<string, EventLineWorkspaceState>>({});
  const eventLineAutoLoadDedupeRef = useRef<Record<string, number>>({});
  const eventLineRequestSeqRef = useRef(0);
  const currentEventLineState = eventLineStatesBySandbox[eventLineWorkspaceKey] || EMPTY_EVENT_LINE_WORKSPACE_STATE;
  const eventLines = currentEventLineState.items;
  const eventLinesLoadError = currentEventLineState.error;
  const eventLinesLoading = currentEventLineState.status === 'loading';
  const eventLineFilterStorageKey = `${EVENT_LINE_PROJECT_FILTER_STORAGE_KEY}:${eventLineWorkspaceKey}`;
  const [eventLineProjectFilterId, setEventLineProjectFilterId] = useState<string>(() => {
    if (typeof window === 'undefined') return '__all__';
    return window.localStorage.getItem(eventLineFilterStorageKey) || '__all__';
  });

  const updateEventLineWorkspaceState = useCallback((
    sandboxId: string,
    updater: EventLineWorkspaceState | ((current: EventLineWorkspaceState) => EventLineWorkspaceState),
  ) => {
    const key = sandboxId || 'local';
    setEventLineStatesBySandbox((prev) => {
      const current = prev[key] || EMPTY_EVENT_LINE_WORKSPACE_STATE;
      const next = typeof updater === 'function' ? updater(current) : updater;
      if (next === current) return prev;
      return { ...prev, [key]: next };
    });
  }, []);

  useEffect(() => {
    eventLineStatesBySandboxRef.current = eventLineStatesBySandbox;
  }, [eventLineStatesBySandbox]);

  const setEventLines = useCallback((next: React.SetStateAction<EventLine[]>) => {
    const sandboxId = currentActiveSandboxId() || eventLineWorkspaceKey || 'local';
    updateEventLineWorkspaceState(sandboxId, (current) => {
      const items = typeof next === 'function'
        ? (next as (prev: EventLine[]) => EventLine[])(current.items)
        : next;
      return {
        ...current,
        items,
        status: 'loaded',
        error: null,
        loadedAt: Date.now(),
      };
    });
  }, [eventLineWorkspaceKey, updateEventLineWorkspaceState]);

  const loadEventLines = useCallback(async (options?: { resetFilter?: boolean; transition?: WorkspaceTransitionToken }) => {
    const sandboxAtStart = options?.transition?.sandboxId || currentActiveSandboxId() || eventLineWorkspaceKey || 'local';
    const requestId = eventLineRequestSeqRef.current + 1;
    eventLineRequestSeqRef.current = requestId;
    if (options?.resetFilter) setEventLineProjectFilterId('__all__');
    updateEventLineWorkspaceState(sandboxAtStart, (current) => ({
      ...current,
      status: 'loading',
      error: null,
      requestId,
    }));
    console.info('[event-lines] load start', {
      sandboxId: sandboxAtStart,
      requestId,
      reason: options?.transition?.reason || 'manual-or-effect',
    });
    try {
      const records = await getEventLines();
      updateEventLineWorkspaceState(sandboxAtStart, (current) => {
        if (current.requestId !== requestId) {
          console.info('[event-lines] load discarded', {
            sandboxId: sandboxAtStart,
            requestId,
            currentRequestId: current.requestId,
            reason: 'newer-request',
          });
          return current;
        }
        console.info('[event-lines] load applied', {
          sandboxId: sandboxAtStart,
          requestId,
          count: records.length,
        });
        return {
          items: records,
          status: 'loaded',
          error: null,
          requestId,
          loadedAt: Date.now(),
        };
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : '事件线加载失败';
      console.warn('[event-lines] load failed', { sandboxId: sandboxAtStart, requestId, error });
      updateEventLineWorkspaceState(sandboxAtStart, (current) => {
        if (current.requestId !== requestId) return current;
        return {
          ...current,
          status: 'failed',
          error: message,
          requestId,
        };
      });
    }
  }, [eventLineWorkspaceKey, updateEventLineWorkspaceState]);
  loadEventLinesForWorkspaceRef.current = loadEventLines;

  const requestEventLinesForCurrentWorkspace = useCallback((
    reason: string,
    options?: { resetFilter?: boolean; forceEmptyRetry?: boolean },
  ) => {
    if (!canLoadCurrentWorkspaceBusinessData) return;
    const sandboxId = currentActiveSandboxId() || eventLineWorkspaceKey || 'local';
    const current = eventLineStatesBySandboxRef.current[sandboxId] || EMPTY_EVENT_LINE_WORKSPACE_STATE;
    if (current.status === 'loading') return;
    if (current.status === 'loaded' && current.items.length > 0) return;
    if (!options?.forceEmptyRetry && current.status === 'loaded') return;
    const dedupeKey = `${sandboxId}:${reason}:${current.status}:${current.items.length}`;
    if (eventLineAutoLoadDedupeRef.current[dedupeKey]) return;
    eventLineAutoLoadDedupeRef.current[dedupeKey] = Date.now();
    console.info('[event-lines] auto load requested', {
      sandboxId,
      reason,
      status: current.status,
      count: current.items.length,
    });
    void loadEventLines({ resetFilter: options?.resetFilter ?? false });
  }, [canLoadCurrentWorkspaceBusinessData, eventLineWorkspaceKey, loadEventLines]);

  const applyWorkspaceRuntime = (
    workspace: SandboxWorkspaceRecord | null | undefined,
    auth: AuthState | null | undefined,
  ) => {
    const nextRuntime = resolveWorkspaceRuntimeFromRecord(workspace, auth);
    markWorkspaceRuntime(nextRuntime.status, nextRuntime.message);
    return nextRuntime;
  };

  const refreshCurrentWorkspaceRuntime = async (
    auth: AuthState | null | undefined,
    transition?: WorkspaceTransitionToken | null,
    reason = 'refresh-current-workspace-runtime',
  ) => {
    try {
      const workspace = await getCurrentWorkspace();
      if (!shouldApplyWorkspaceLoad(transition)) return null;
      if (workspace?.id) {
        activeSandboxIdRef.current = workspace.id;
        if (transition) pinWorkspaceTransitionSandbox(transition, workspace.id);
      }
      const runtime = applyWorkspaceRuntime(workspace, auth);
      console.info('[workspace-runtime] refreshed current workspace', {
        reason,
        sandboxId: workspace?.id,
        runtimeStatus: runtime.status,
      });
      return workspace;
    } catch (error) {
      console.warn('[workspace-runtime] failed to refresh current workspace', { reason, error });
      return null;
    }
  };

  const reconcileStaleWorkspaceRuntime = useCallback((reason: string) => {
    if (workspaceRuntimeRecoveryInFlightRef.current) return;
    if (!workspaceRuntimeBlocksWrites(workspaceRuntimeStatusRef.current)) return;
    workspaceRuntimeRecoveryInFlightRef.current = true;
    void refreshCurrentWorkspaceRuntime(authState, workspaceTransitionRef.current, reason)
      .catch((error) => {
        console.warn('[workspace-runtime] stale runtime recovery failed', { reason, error });
      })
      .finally(() => {
        workspaceRuntimeRecoveryInFlightRef.current = false;
      });
  }, [authState]);

  useEffect(() => {
    if (loading || !workspaceWritesBlocked) return undefined;
    const timer = window.setTimeout(() => {
      if (loading) return;
      const currentStatus = workspaceRuntimeStatusRef.current;
      if (!workspaceRuntimeBlocksWrites(currentStatus)) return;
      const ageMs = Date.now() - workspaceRuntimeLastMarkedAtRef.current;
      console.warn('[workspace-runtime] write-blocking state remained after loading finished; reconciling from backend', {
        status: currentStatus,
        ageMs,
      });
      reconcileStaleWorkspaceRuntime('write-blocking-state-after-loading-finished');
    }, 600);
    return () => window.clearTimeout(timer);
  }, [loading, reconcileStaleWorkspaceRuntime, workspaceRuntimeStatus, workspaceWritesBlocked]);

  const isLocalServiceStartupError = (error: unknown) => {
    const detail = error instanceof Error ? error.message : String(error ?? '');
    return detail.includes('无法连接本地服务');
  };

  const clearLocalServiceStartupBanner = () => {
    const currentBanner = getGlobalBanner();
    // 按原始文案匹配(人话化后 text 已变, 用 rawText 兜底)
    const matchText = currentBanner?.rawText ?? currentBanner?.text ?? '';
    if (!currentBanner || currentBanner.type !== 'error' || !matchText.includes('无法连接本地服务')) return;
    clearGlobalBanner();
  };

  useEffect(() => {
    if (health?.backend === 'online') {
      backendReadyRef.current = true;
      clearLocalServiceStartupBanner();
    }
  }, [health?.backend, health?.startedAt]);

  useEffect(() => {
    syncNavigationStateToUrl(activeTab, settingsSection);
  }, [activeTab, settingsSection]);

  useEffect(() => {
    const syncOfficialPushFlag = () => {
      const nextPush = window[UPDATE_STATE_KEY]?.officialPush ?? null;
      setHasOfficialPush(Boolean(nextPush));
      setOfficialPushToast(nextPush);
    };
    syncOfficialPushFlag();
    window.addEventListener(OFFICIAL_PUSH_STATE_EVENT, syncOfficialPushFlag);
    return () => {
      window.removeEventListener(OFFICIAL_PUSH_STATE_EVENT, syncOfficialPushFlag);
    };
  }, []);

  useEffect(() => {
    const handlePopState = () => {
      const nextState = normalizeStartupNavigationState(readInitialNavigationState());
      setActiveTab(nextState.activeTab);
      setSettingsSection(nextState.settingsSection);
      setEvidenceMode(nextState.evidenceMode);
      setEvidenceTaskId(nextState.evidenceTaskId);
      setEvidenceClientId(nextState.evidenceClientId);
      setWorkspaceThreadPreference(nextState.workspaceThreadPreference);
    };
    window.addEventListener('popstate', handlePopState);
    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, []);

  async function refreshMaintenanceModeStatus(options: { silent?: boolean; workspace?: SandboxWorkspaceRecord | null } = {}) {
    const targetWorkspace = options.workspace === undefined ? activeWorkspaceRecord : options.workspace;
    if (
      !canUseCollabSync
      || !hasAuthenticatedSession
      || !isCloudSession
      || currentMembershipStatus !== 'approved'
      || !isYiyuOfficialWorkspaceRecord(targetWorkspace)
    ) {
      setMaintenanceModeStatus(null);
      setMaintenanceModeError(null);
      setIsMaintenanceModeLoading(false);
      setMaintenanceModeBusyAction(null);
      return null;
    }
    setIsMaintenanceModeLoading(true);
    setMaintenanceModeError(null);
    try {
      const status = await getMaintenanceModeStatus();
      setMaintenanceModeStatus(status);
      return status;
    } catch (error) {
      const message = error instanceof Error ? error.message : '维护模式状态加载失败';
      setMaintenanceModeStatus(null);
      setMaintenanceModeError(message);
      if (!options.silent) {
        flash('error', message);
      }
      return null;
    } finally {
      setIsMaintenanceModeLoading(false);
    }
  }

  async function handleEnterMaintenanceMode() {
    setMaintenanceModeBusyAction('enter');
    setMaintenanceModeError(null);
    try {
      const status = await enterMaintenanceMode();
      setMaintenanceModeStatus(status);
      flash('success', '左下角推送同步已打开。');
      await refreshCollabStatus(collabRepoPath);
    } catch (error) {
      const message = error instanceof Error ? error.message : '维护模式打开失败';
      setMaintenanceModeError(message);
      flash('error', message);
    } finally {
      setMaintenanceModeBusyAction(null);
    }
  }

  async function handleExitMaintenanceMode() {
    setMaintenanceModeBusyAction('exit');
    setMaintenanceModeError(null);
    try {
      const status = await exitMaintenanceMode();
      setMaintenanceModeStatus(status);
      setCollabDialogState(null);
      setCollabSelectedPaths([]);
      setCollabCommitMessage('');
      setCollabDialogError(null);
      flash('success', '左下角推送同步已关闭。');
    } catch (error) {
      const message = error instanceof Error ? error.message : '维护模式关闭失败';
      setMaintenanceModeError(message);
      flash('error', message);
    } finally {
      setMaintenanceModeBusyAction(null);
    }
  }

  async function refreshCollabStatus(nextRepoPath = collabRepoPath) {
    if (!canUseCollabSync) {
      return null;
    }
    setIsCollabStatusLoading(true);
    try {
      const requestedRepoPath = normalizeInitialCollabRepoPath(nextRepoPath);
      const nextStatus = await getCollabRepoStatus(requestedRepoPath);
      const normalizedStatus: CollabRepoStatus = {
        ...nextStatus,
        repoPath: normalizeInitialCollabRepoPath(nextStatus.repoPath),
        suggestedRepoPath: normalizeInitialCollabRepoPath(nextStatus.suggestedRepoPath || null),
        workingRepoPath: normalizeInitialCollabRepoPath(nextStatus.workingRepoPath || null),
      };
      setCollabStatus(normalizedStatus);
      if (normalizedStatus.repoPath && normalizedStatus.repoPath !== requestedRepoPath && normalizedStatus.isValid) {
        setCollabRepoPath(normalizedStatus.repoPath);
      }
      return normalizedStatus;
    } catch (error) {
      flash('error', error instanceof Error ? error.message : '源码仓库状态加载失败');
      return null;
    } finally {
      setIsCollabStatusLoading(false);
    }
  }

  function getDefaultCollabSelectedPaths(state: Exclude<CollabDialogState, null>) {
    return state.preview.files.map((file) => file.path);
  }

  function openCollabDialog(state: Exclude<CollabDialogState, null>) {
    setCollabDialogState(state);
    setCollabSelectedPaths(getDefaultCollabSelectedPaths(state));
    setCollabCommitMessage(state.preview.suggestedMessage);
    setCollabDialogError(null);
  }

  async function ensureCollabRepoForAction() {
    if (!canUseCollabSync) {
      flash('error', '协作同步仅在桌面版可用，请在 Electron 应用中打开。');
      return null;
    }
    if (!isMaintenanceModeActive) {
      flash('error', '请先在系统日志中打开左下角推送同步。');
      void refreshMaintenanceModeStatus({ silent: true });
      return null;
    }
    if (collabStatus?.isConfigured && collabStatus.isValid && !collabStatus.isMainBranch && collabStatus.suggestedRepoPath) {
      setCollabRepoPath(collabStatus.suggestedRepoPath);
      return collabStatus.suggestedRepoPath;
    }
    if (collabStatus?.repoPath && collabStatus.isValid) {
      if (collabStatus.repoPath !== collabRepoPath) {
        setCollabRepoPath(collabStatus.repoPath);
      }
      return collabStatus.repoPath;
    }
    if (collabStatus?.suggestedRepoPath) {
      setCollabRepoPath(collabStatus.suggestedRepoPath);
      return collabStatus.suggestedRepoPath;
    }
    const nextRepoPath = normalizeInitialCollabRepoPath(await selectCollabRepoBridge());
    if (!nextRepoPath) return null;
    const selectedStatus = await refreshCollabStatus(nextRepoPath);
    if (!selectedStatus?.isValid || !selectedStatus.repoPath) {
      flash('error', selectedStatus?.statusText || '所选目录不是有效的严格新版源码仓库。');
      return null;
    }
    setCollabRepoPath(selectedStatus.repoPath);
    setCollabDialogState(null);
    setCollabSelectedPaths([]);
    setCollabCommitMessage('');
    setCollabDialogError(null);
    flash('success', '源码目录已绑定，后续协作按钮会围绕这个仓库工作。');
    return selectedStatus.repoPath;
  }

  async function handlePreviewPush() {
    const repoPath = await ensureCollabRepoForAction();
    if (!repoPath) {
      return;
    }
    setCollabBusyAction('push');
    try {
      const preview = await previewPushToMain(repoPath);
      const nextState = { mode: 'push' as const, preview };
      openCollabDialog(nextState);
    } catch (error) {
      flash('error', error instanceof Error ? error.message : '推送预览失败');
    } finally {
      setCollabBusyAction(null);
    }
  }

  async function handlePreviewPull() {
    const repoPath = await ensureCollabRepoForAction();
    if (!repoPath) {
      return;
    }
    setCollabBusyAction('pull');
    try {
      const preview = await previewPullFromMain(repoPath);
      const nextState = { mode: 'pull' as const, preview };
      openCollabDialog(nextState);
    } catch (error) {
      flash('error', error instanceof Error ? error.message : '同步预览失败');
    } finally {
      setCollabBusyAction(null);
    }
  }

  async function handleSelectPullCommit(targetCommit: string | null) {
    if (!canUseCollabSync) return;
    if (!isMaintenanceModeActive) {
      setCollabDialogError('请先在系统日志中打开左下角推送同步。');
      void refreshMaintenanceModeStatus({ silent: true });
      return;
    }
    const repoPath = collabRepoPath || collabStatus?.repoPath;
    if (!repoPath || collabBusyAction === 'pull') return;
    setCollabBusyAction('pull');
    setCollabDialogError(null);
    try {
      const preview = await previewPullFromMain(repoPath, targetCommit);
      const nextState = { mode: 'pull' as const, preview };
      openCollabDialog(nextState);
    } catch (error) {
      const message = error instanceof Error ? error.message : '按提交日期切换同步范围失败';
      if (collabDialogState?.mode === 'pull') {
        setCollabDialogError(message);
      } else {
        flash('error', message);
      }
    } finally {
      setCollabBusyAction(null);
    }
  }

  async function handleConfirmCollabAction() {
    if (!canUseCollabSync) return;
    if (!collabDialogState) return;
    if (!isMaintenanceModeActive) {
      setCollabDialogError('请先在系统日志中打开左下角推送同步。');
      void refreshMaintenanceModeStatus({ silent: true });
      return;
    }
    const repoPath = collabRepoPath || collabStatus?.repoPath;
    if (!repoPath) {
      setCollabDialogError('还没有绑定源码目录。');
      return;
    }
    const mode = collabDialogState.mode;
    setCollabDialogError(null);
    setCollabBusyAction(mode);
    try {
      let result: CollabActionResult;
      if (mode === 'push') {
        result = await pushSafelyToMain({
          repoPath,
          message: collabCommitMessage.trim() || collabDialogState.preview.suggestedMessage,
        });
      } else {
        result = await fastForwardMain({ repoPath });
      }
      flash('success', mode === 'push'
        ? '已安全推送到 GitHub main。'
        : '已快进接收 origin/main。');
      setCollabDialogState(null);
      setCollabSelectedPaths([]);
      setCollabCommitMessage('');
      setCollabDialogError(null);
      await refreshCollabStatus(repoPath);
      if (mode === 'pull') {
        if (currentSessionUser?.primaryRole === 'admin') {
          await loadSystemAdminSettingsBlock(true).catch((error) => {
            console.warn('[strict-collab] admin settings refresh skipped after pull', error);
          });
        }
        if (desktopAppInfo?.isPackaged) {
          setCollabBusyAction('rebuild');
          flash('success', '源码已同步，正在构建并覆盖安装；完成后软件会自动重启。');
          try {
            const rebuild = await rebuildAndInstallFromRepo(repoPath);
            if (rebuild.state === 'installing') {
              flash('success', rebuild.message);
            } else if (rebuild.state === 'not_packaged') {
              flash('success', rebuild.message);
            } else {
              flash('info', rebuild.message);
            }
          } catch (error) {
            const message = error instanceof Error ? error.message : '本机自动构建或覆盖安装失败';
            flash('error', `源码已成功接收；${message}`);
          }
        } else {
          flash('success', '源码已同步；当前开发版会直接读取最新界面。');
        }
      }
    } catch (error) {
      setCollabDialogError(error instanceof Error ? error.message : '协作操作失败');
      await refreshCollabStatus(repoPath);
    } finally {
      setCollabBusyAction(null);
    }
  }

  async function handleStartCollabPreview(targetRef?: string, label?: string) {
    if (!canUseCollabSync) return;
    if (!collabDialogState) return;
    if (!isMaintenanceModeActive) {
      setCollabDialogError('请先在系统日志中打开左下角推送同步。');
      void refreshMaintenanceModeStatus({ silent: true });
      return;
    }
    const repoPath = collabRepoPath || collabStatus?.repoPath;
    if (!repoPath) {
      setCollabDialogError('还没有绑定源码目录。');
      return;
    }
    const fallbackRef = collabDialogState.mode === 'pull'
      ? (collabDialogState.preview.syncTargetCommit || 'origin/main')
      : 'origin/main';
    setCollabDialogError(null);
    setCollabBusyAction('pull');
    try {
      const result = await startCollabPreview({
        repoPath,
        targetRef: targetRef || fallbackRef,
        label: label || null,
      });
      if (result.previewSession) {
        setCollabPreviewSession(result.previewSession);
      }
      flash('success', result.explanation || '协作预览已开启。');
    } catch (error) {
      setCollabDialogError(error instanceof Error ? error.message : '协作预览开启失败');
    } finally {
      setCollabBusyAction(null);
    }
  }

  async function handleStopCollabPreview() {
    if (!collabPreviewSession) return;
    setCollabBusyAction('pull');
    setCollabDialogError(null);
    try {
      await stopCollabPreview({ previewId: collabPreviewSession.previewId });
      setCollabPreviewSession(null);
      flash('success', '协作预览已停止。');
    } catch (error) {
      setCollabDialogError(error instanceof Error ? error.message : '协作预览停止失败');
    } finally {
      setCollabBusyAction(null);
    }
  }

  function handleCollabMessageChange(nextValue: string) {
    setCollabDialogError(null);
    setCollabCommitMessage(nextValue);
  }

  async function loadSettingsBlock(options?: { applyRuntime?: boolean; transition?: WorkspaceTransitionToken }) {
    const startedSandboxId = options?.transition?.sandboxId || currentActiveSandboxId();
    // Workspace identity is the startup authority.  A peripheral settings
    // failure must never discard a workspace that has already loaded
    // successfully (this previously made an admin login look ineffective).
    const workspaces = await getWorkspaces().catch(() => null);
    const canApply = shouldApplyWorkspaceLoad(options?.transition, startedSandboxId);
    if (canApply) {
      setWorkspacesState(workspaces);
      if (workspaces?.activeSandboxId) {
        activeSandboxIdRef.current = workspaces.activeSandboxId;
      }
    }
    const nextActiveWorkspace = workspaces?.workspaces.find((item) => item.id === workspaces.activeSandboxId) || null;
    if (canApply && options?.applyRuntime !== false && !WORKSPACE_BUSY_RUNTIME_STATUSES.has(workspaceRuntimeStatusRef.current)) {
      applyWorkspaceRuntime(nextActiveWorkspace, authState);
    }
    let response: Awaited<ReturnType<typeof getSettings>>;
    try {
      response = await getSettings();
    } catch (error) {
      // The workspace is already authoritative and usable.  Keep it active
      // while a settings card retries independently instead of rolling the
      // whole shell back to an anonymous/no-workspace appearance.
      if (workspaces) {
        if (canApply) clearLocalServiceStartupBanner();
        console.warn('[settings] settings load failed after workspace recovery', error);
        return { settings: settingsState, workspaces, settingsError: error };
      }
      throw error;
    }
    if (canApply) {
      setSettingsState(response.settings);
      setOperators(response.operators);
      setHealth(response.health);
    }
    if (canApply) clearLocalServiceStartupBanner();
    const missingFeatures = REQUIRED_BACKEND_FEATURES.filter((feature) => !response.health.featureFlags.includes(feature));
    if (canApply) {
      setBackendCompatibilityError(
        missingFeatures.length > 0 ? `本地后端版本过旧，请重启应用。缺少能力：${missingFeatures.join('、')}` : null,
      );
    }
    return { settings: response.settings, workspaces, settingsError: null };
  }

  async function loadOrgAiRuntimeBlock(options?: {
    sync?: boolean;
    transition?: WorkspaceTransitionToken;
    timeoutMs?: number;
  }) {
    const startedSandboxId = options?.transition?.sandboxId || currentActiveSandboxId();
    const request = options?.sync
      ? syncOrgAiRuntime({ automatic: true })
      : getOrgAiRuntimeStatus();
    let timer: number | null = null;
    try {
      const response = options?.timeoutMs
        ? await Promise.race<OrgAiRuntimeStatus | null>([
            request,
            new Promise<null>((resolve) => {
              timer = window.setTimeout(() => resolve(null), options.timeoutMs);
            }),
          ])
        : await request;
      if (response && shouldApplyWorkspaceLoad(options?.transition, startedSandboxId)) {
        setOrgAiRuntimeStatus(response);
      }
      if (options?.sync && (!response || response.state === 'syncing')) {
        void (async () => {
          for (let attempt = 0; attempt < 8; attempt += 1) {
            await new Promise((resolve) => window.setTimeout(resolve, 1000));
            if (!shouldApplyWorkspaceLoad(options.transition, startedSandboxId)) return;
            try {
              const latest = await getOrgAiRuntimeStatus();
              if (!shouldApplyWorkspaceLoad(options.transition, startedSandboxId)) return;
              setOrgAiRuntimeStatus(latest);
              if (latest.state !== 'syncing') {
                await loadSettingsBlock({ applyRuntime: false, transition: options.transition });
                return;
              }
            } catch {
              // The manual retry entry remains available after the bounded poll.
            }
          }
        })();
      }
      return response;
    } finally {
      if (timer !== null) window.clearTimeout(timer);
    }
  }

  async function handleSyncOrgAiRuntime() {
    if (orgAiRuntimeSyncing) return;
    setOrgAiRuntimeSyncing(true);
    setOrgAiRuntimeStatus((previous) => previous ? { ...previous, state: 'syncing', lastError: null } : previous);
    try {
      const result = await syncOrgAiRuntime();
      setOrgAiRuntimeStatus(result);
      await loadSettingsBlock({ applyRuntime: false });
      if (result.state === 'ready_direct') {
        flash('success', `${result.providerLabel || result.model || '组织 AI'} 已同步，可在本机直接使用`);
      } else {
        flash('error', result.lastError || '组织 AI 尚未就绪，请确认管理员已保存组织配置');
      }
    } catch (error) {
      const detail = error instanceof Error ? error.message : '组织 AI 配置同步失败';
      setOrgAiRuntimeStatus((previous) => previous ? { ...previous, state: 'error', lastError: detail } : previous);
      flash('error', detail);
    } finally {
      setOrgAiRuntimeSyncing(false);
    }
  }

