  async function loadSettingsSectionBlock(section: SettingsSectionKey, force = false) {
    const startedSandboxId = currentActiveSandboxId();
    if (!force && settingsSectionLoaded[section]) return;
    switch (section) {
      case 'overview':
        await Promise.all([loadSpeechModelSettingsBlock(), loadObjectStorageSettingsBlock()]);
        break;
      case 'tasks':
        await loadTaskSettingsBlock();
        break;
      case 'client_workspace':
        await loadClientWorkspaceSettingsBlock();
        break;
      case 'topics':
        await loadTopicsSettingsBlock();
        break;
      case 'handbook':
        await loadHandbookSettingsBlock();
        break;
      case 'system_admin':
      case 'org_overview':
      case 'org_departments':
      case 'org_people':
      case 'org_rules':
        if (currentSessionUser?.primaryRole !== 'admin' && canClaimOrgAdmin) {
          await loadOrgAdminClaimStatusBlock(true);
        } else {
          await loadSystemAdminSettingsBlock(authState.sessionMode === 'cloud');
        }
        break;
    }
    if (shouldApplyWorkspaceLoad(null, startedSandboxId)) {
      setSettingsSectionLoaded((prev) => ({ ...prev, [section]: true }));
    }
  }

