  async function loadClientBlock(
    nextClientId?: string,
    options?: { transition?: WorkspaceTransitionToken; organizationId?: string | null },
  ) {
    const startedSandboxId = options?.transition?.sandboxId || currentActiveSandboxId();
    const canApply = () => shouldApplyWorkspaceLoad(options?.transition, startedSandboxId);
    let clientItems: ClientSummary[];
    try {
      clientItems = await getClients();
    } catch (error) {
      // 客户列表加载失败(断网 / 后端瞬态)时,保留上次已加载的客户,绝不清空、绝不向上抛错中断引导链。
      // 跟 loadEventLines 一样做到 local-first 容错 —— 这是"客户没了、时间线还在"非对称的根治点:
      // 让客户和时间线在离线时同等健壮,而不是悄悄退化成空列表(再被推断回落到益语智库)。
      console.error('[bootstrap] loadClientBlock getClients failed; 保留上次客户列表不清空', error);
      clearLocalServiceStartupBanner();
      return;
    }
    if (!canApply()) return;
    console.info(`[bootstrap] loadClientBlock fetched clients=${clientItems.length}`);
    setClients(clientItems);
    // 选项目优先级：显式目标、上次选择、当前项目、首个可见项目。
    const persistedClientId = readStoredClientId(window.localStorage, {
      sandboxId: startedSandboxId,
      organizationId: options?.organizationId || authState.user?.organizationId,
    });
    const preferredClientId =
      (nextClientId && clientItems.some((item) => item.id === nextClientId) && nextClientId) ||
      (persistedClientId
        && clientItems.some((item) => item.id === persistedClientId)
        && persistedClientId) ||
      (currentClientId
        && clientItems.some((item) => item.id === currentClientId)
        && currentClientId) ||
      clientItems[0]?.id ||
      '';
    const targetClientId = preferredClientId;
    if (targetClientId) {
      const token = workspaceLoadGateRef.current.begin(scopedAsyncKey(
        startedSandboxId,
        options?.organizationId || authState.user?.organizationId,
        targetClientId,
      ));
      currentClientIdRef.current = targetClientId;
      // 防御:值相同时跳过 setState,避免触发监听 currentClientId 的 effect 链多次重跑
      if (currentClientId !== targetClientId) {
        setCurrentClientId(targetClientId);
      }
      console.info(`[bootstrap] loadClientBlock selecting client=${targetClientId}`);
      try {
        const nextWorkspace = await getClientWorkspace(targetClientId);
        if (
          !workspaceLoadGateRef.current.accepts(token)
          || currentClientIdRef.current !== targetClientId
          || !canApply()
        ) return;
        setWorkspace(nextWorkspace);
        void loadClientPageContextBlock(targetClientId, options);
        void loadWorkspacePersistedProposalDraftsBlock(targetClientId, options);
        void loadProposalBlock(targetClientId, options);
      } catch (error) {
        if (
          !workspaceLoadGateRef.current.accepts(token)
          || currentClientIdRef.current !== targetClientId
          || !canApply()
        ) return;
        console.error('[bootstrap] loadClientBlock workspace fetch failed', error);
        setWorkspace(null);
        setWorkspacePageContext(null);
        flash('error', error instanceof Error ? error.message : '项目工作区加载失败');
      }
    } else {
      console.warn('[bootstrap] loadClientBlock found no selectable client');
      setCurrentClientId('');
      setWorkspace(null);
      setWorkspacePageContext(null);
      setWorkspacePersistedProposalDrafts([]);
    }
    clearLocalServiceStartupBanner();
  }

