  async function loadOrganizationPlanningBlock(options?: {
    transition?: WorkspaceTransitionToken;
    organizationId?: string | null;
    force?: boolean;
  }) {
    const requestedOrganizationId = (
      options?.organizationId ?? authState.user?.organizationId ?? ''
    ).trim();
    const scopeKey = [
      currentActiveSandboxId(),
      viewerAuthorization?.membershipId || currentSessionUser?.id || '',
      requestedOrganizationId,
    ].join('|');
    const cached = organizationPlanningCacheRef.current;
    const hasCurrentScopeCache = cached.scopeKey === scopeKey && cached.loadedAt > 0;
    // 组织计划是低频变化的权威快照。页面切换本身不构成失效条件；保存计划、
    // 任务改挂计划、删除任务和工作空间切换已经会显式 force/清空缓存。
    // 因此只要仍在同一 sandbox + membership + organization，就直接复用，
    // 避免每隔五分钟或反复切页时重新出现整页加载。
    if (!options?.force && hasCurrentScopeCache) {
      setOrganizationPlanningLoadError('');
      setIsOrganizationPlanningLoading(false);
      return {
        departments: departmentOptions,
        cycles: strictPlanningCycles,
        actions: strictDecisionActions,
      };
    }
    const requestId = organizationPlanningRequestRef.current + 1;
    organizationPlanningRequestRef.current = requestId;
    // 同一工作空间的旧快照已可用时，过期刷新只在后台进行，不先把页面
    // 替换成加载态。首次进入或真正切换工作空间时才显示阻塞加载。
    setIsOrganizationPlanningLoading(!hasCurrentScopeCache);
    setOrganizationPlanningLoadError('');
    try {
      const [departments, cycles, actions] = await Promise.all([
        getDepartmentOptions({
          organizationId: requestedOrganizationId || null,
        }),
        gc06Api.listPlanningCycles(true),
        gc06Api.listDecisionActions(),
      ]);
    // 只接受最后一次组织计划请求。sandbox 激活/重启过程中 transition token 和
    // activeSandboxId 的更新顺序并不稳定，直接比较两者会把当前组织的 200 回包
    // 误判为迟到数据。工作空间清理会先递增同一个代次，因此这里只接受最后
    // 一次请求已经足以保证跨 sandbox 隔离，也不会受 auth React 闭包更新顺序影响。
    // React StrictMode 会在开发版执行一次探测性的 setup→cleanup→setup；用组件
    // mounted ref 作为第二重门禁，会在冷启动时把成功的严格接口回包误丢弃。
    // 请求代次已由工作空间清理递增，最后一次请求才可落状态，足以同时保证
    // 跨 sandbox 隔离和迟到回包淘汰。
      const canApply = requestId === organizationPlanningRequestRef.current;
      if (canApply) {
      // 部门、计划周期和行动必须作为同一个工作空间快照一起生效。若分散到
      // auth effect / task-board 的 fire-and-forget 中，启动清理或请求序号变化会
      // 只留下“当前组织”，并把真实部门计划误显示为空。
        flushSync(() => {
          setDepartmentOptions(departments);
          setStrictPlanningCycles(cycles);
          setStrictDecisionActions(actions);
        });
        organizationPlanningCacheRef.current = { scopeKey, loadedAt: Date.now() };
      }
      return { departments, cycles, actions };
    } catch (error) {
      if (requestId === organizationPlanningRequestRef.current) {
        setOrganizationPlanningLoadError(error instanceof Error ? error.message : '组织计划加载失败');
      }
      throw error;
    } finally {
      if (requestId === organizationPlanningRequestRef.current) {
        setIsOrganizationPlanningLoading(false);
      }
    }
  }

  async function loadAll(nextClientId?: string, options?: { allowStartupRetry?: boolean }) {
    // 防御:loadAll 已在执行时,新调用直接 noop,避免某个不稳定 effect 反复触发 loadAll 导致死循环
    if (loadAllInFlightRef.current) {
      console.warn('[bootstrap] loadAll already in flight, skipping reentry');
      return;
    }
    loadAllInFlightRef.current = true;
    const transitionToken = beginWorkspaceTransition('verifying', '正在连接本地后端…', {
      sandboxId: activeSandboxIdRef.current || workspacesState?.activeSandboxId || '',
      reason: 'load-all',
    });
    resetFeishuWorkspaceTransientState();
    resetBusinessWorkspaceTransientState();
    let keepLoadingForRetry = false;
    let latestAuthForRuntime: AuthState | null = null;
    try {
      await waitForLocalBackendReady();
      if (!shouldApplyWorkspaceLoad(transitionToken)) return;
      markLoadingPhase('正在恢复登录状态…');
      let nextAuth = await loadAuthBlock({ transition: transitionToken });
      if (!shouldApplyWorkspaceLoad(transitionToken)) return;
      nextAuth = await recoverIncompleteAuthBlock(nextAuth, { transition: transitionToken });
      latestAuthForRuntime = nextAuth;
      if (!shouldApplyWorkspaceLoad(transitionToken)) return;
      let loadedWorkspaces: SandboxWorkspacesResponse | null = null;
      try {
        markLoadingPhase('正在读取系统设置…');
        const settingsBlock = await loadSettingsBlock({ applyRuntime: false, transition: transitionToken });
        loadedWorkspaces = settingsBlock.workspaces;
        if (loadedWorkspaces) pinWorkspaceTransitionSandbox(transitionToken, loadedWorkspaces.activeSandboxId);
        await loadLocalInputMemoryBlock({ transition: transitionToken });
      } catch (settingsError) {
        if (isLocalServiceStartupError(settingsError)) {
          window.setTimeout(() => {
            void Promise.all([loadSettingsBlock(), loadLocalInputMemoryBlock()]).catch(() => undefined);
          }, 1500);
        } else {
          flash('error', settingsError instanceof Error ? settingsError.message : '系统设置加载失败');
        }
      }
      const loadedActiveWorkspace = loadedWorkspaces?.workspaces.find((item) => item.id === loadedWorkspaces?.activeSandboxId) || null;
      pinWorkspaceTransitionSandbox(transitionToken, loadedActiveWorkspace?.id || loadedWorkspaces?.activeSandboxId || null);
      if (!shouldApplyWorkspaceLoad(transitionToken)) return;
      const runtime = resolveWorkspaceRuntimeFromRecord(loadedActiveWorkspace, nextAuth);
      if (runtime.status === 'needs_login' || runtime.status === 'identity_error') {
        markWorkspaceRuntime(runtime.status, runtime.message);
        resetFeishuWorkspaceTransientState();
        resetBusinessWorkspaceTransientState();
        markLoadingPhase(runtime.message);
        setSettingsSectionLoaded({
          overview: true,
          account: false,
          tasks: true,
          client_workspace: false,
          topics: false,
          handbook: false,
          system_admin: false,
          org_overview: false,
          org_departments: false,
          org_people: false,
          org_rules: false,
          system_logs: false,
          about: false,
        });
        startupRetryRef.current = 0;
        clearLocalServiceStartupBanner();
        return;
      }
      if (runtime.status === 'local_draft') {
        markWorkspaceRuntime('local_draft', runtime.message);
      } else {
        markWorkspaceRuntime('verifying', '正在验证工作空间身份…');
      }
      let nextOrgAdminClaimStatus = DEFAULT_ORG_ADMIN_CLAIM_STATUS;
      // Always load org membership for cloud-authenticated users so the account-settings page
      // shows up-to-date organizationName / departmentName (even after a dept lead was bound
      // after the user already had approved status).
      if (hasCompleteSessionIdentity(nextAuth) && nextAuth.sessionMode === 'cloud') {
        await loadOrgMembershipBlock({ transition: transitionToken }).catch(() => DEFAULT_ORG_MEMBERSHIP_SUMMARY);
        nextOrgAdminClaimStatus = await loadOrgAdminClaimStatusBlock(true, { transition: transitionToken }).catch(() => DEFAULT_ORG_ADMIN_CLAIM_STATUS);
      } else {
        if (shouldApplyWorkspaceLoad(transitionToken)) {
          setOrgAdminClaimStatus(DEFAULT_ORG_ADMIN_CLAIM_STATUS);
        }
      }
      // 仅当云端"明确"返回非 approved 时才进身份闸门并清空本地数据。
      // nextAuth.degraded === true 表示这是断网兜底态(云端没法确认),此时绝不能把"未确认"
      // 当成"被拒绝"——否则会清掉上次已加载的客户列表,正是"断网后客户只剩益语智库"的成因。
      // 降级态走 else-if 正常加载分支,沿用本地 last-known-good。
      if (
        hasCompleteSessionIdentity(nextAuth)
        && nextAuth.sessionMode === 'cloud'
        && !nextAuth.degraded
        && getEffectiveMembershipStatus(nextAuth) !== 'approved'
        && !nextOrgAdminClaimStatus.canClaim
      ) {
        markLoadingPhase('正在读取组织身份状态…');
        setClients([]);
        setWorkspace(null);
        setTasks([]);
        setTaskLists([]);
        setTaskTags([]);
        setReviewDashboard(null);
        setRadars([]);
        setCandidates([]);
        setHandbookEntries([]);
        setEmployeeReviews([]);
        setWorkspacePageContext(null);
        setWorkspacePersistedProposalDrafts([]);
        applyWorkspaceRuntime(loadedActiveWorkspace, nextAuth);
      } else if (hasCompleteSessionIdentity(nextAuth)) {
        markWorkspaceRuntime('switching', `正在同步 ${loadedActiveWorkspace?.name || '当前组织'} 的组织 AI 配置…`);
        const aiRuntime = await loadOrgAiRuntimeBlock({ sync: true, transition: transitionToken, timeoutMs: 15000 }).catch(() => null);
        if (!aiRuntime && shouldApplyWorkspaceLoad(transitionToken)) {
          await loadOrgAiRuntimeBlock({ transition: transitionToken }).catch(() => null);
        }
        if (!shouldApplyWorkspaceLoad(transitionToken)) return;
        markWorkspaceRuntime('switching', `正在检查 ${loadedActiveWorkspace?.name || '当前组织'} 的本地任务镜像…`);
        await repairCurrentWorkspaceTaskMirrors().catch((error) => {
          console.warn('[task-mirror-repair] deferred during startup refresh', {
            sandboxId: transitionToken.sandboxId,
            reason: error instanceof Error ? error.message : String(error),
          });
          return null;
        });
        if (!shouldApplyWorkspaceLoad(transitionToken)) return;
        const backgroundLoaders: Array<{ name: string; run: () => Promise<unknown> }> = [
          { name: 'task-settings', run: () => loadTaskSettingsBlock({ transition: transitionToken }) },
          {
            name: 'activity-logs',
            run: () => {
              if (nextAuth.user?.primaryRole === 'admin') {
                return loadLogsBlock({ transition: transitionToken });
              }
              if (shouldApplyWorkspaceLoad(transitionToken)) setLogs([]);
              return Promise.resolve([]);
            },
          },
          { name: 'task-board', run: () => loadTaskBlock({ transition: transitionToken }) },
          {
            name: 'organization-planning',
            run: () => loadOrganizationPlanningBlock({
              transition: transitionToken,
              organizationId: nextAuth.user?.organizationId,
            }),
          },
          {
            name: 'event-lines',
            run: async () => {
              const loader = loadEventLinesForWorkspaceRef.current;
              if (!loader) {
                console.warn('[event-lines] loader not ready during startup load', {
                  sandboxId: transitionToken.sandboxId,
                  reason: transitionToken.reason,
                });
                throw new Error('事件线加载器尚未就绪');
              }
              await loader({ transition: transitionToken, resetFilter: true });
            },
          },
          {
            name: 'agent-worklogs',
            run: () => (nextAuth.user?.primaryRole === 'admin' ? loadAgentWorklogBlock(taskCalendarMonthLabel, { transition: transitionToken }) : Promise.resolve()),
          },
          {
            name: 'reviews',
            run: () => {
              const defaultPerspective = resolveDefaultReviewPerspectiveForUser(nextAuth.user || null);
              return loadReviewBlock(resolveSelectedReviewWeekLabel(), {
                skipAi: true,
                perspective: defaultPerspective,
                departmentId: resolveDefaultReviewDepartmentIdForUser(nextAuth.user || null, defaultPerspective),
                transition: transitionToken,
              });
            },
          },
          { name: 'topics', run: () => loadTopicsBlock({ transition: transitionToken }) },
          { name: 'handbook', run: () => loadHandbookBlock({ transition: transitionToken }) },
          {
            name: 'org-membership',
            run: () =>
              loadOrgMembershipBlock({ transition: transitionToken }).catch(() => {
                if (shouldApplyWorkspaceLoad(transitionToken)) setOrgMembershipState(DEFAULT_ORG_MEMBERSHIP_SUMMARY);
                return DEFAULT_ORG_MEMBERSHIP_SUMMARY;
              }),
          },
          {
            name: 'org-admin-claim-status',
            run: () => loadOrgAdminClaimStatusBlock(nextAuth.sessionMode === 'cloud', { transition: transitionToken }),
          },
          {
            name: 'org-feishu-integration',
            run: () =>
              loadOrgFeishuIntegrationBlock({ transition: transitionToken }).catch(() => {
                if (shouldApplyWorkspaceLoad(transitionToken)) setOrgFeishuIntegrationState(DEFAULT_ORG_FEISHU_INTEGRATION);
                return DEFAULT_ORG_FEISHU_INTEGRATION;
              }),
          },
          {
            name: 'feishu-delivery-profile',
            run: () =>
              loadFeishuDeliveryProfileBlock({ transition: transitionToken }).catch(() => {
                if (shouldApplyWorkspaceLoad(transitionToken)) setFeishuDeliveryProfileState(DEFAULT_FEISHU_DELIVERY_PROFILE);
                return DEFAULT_FEISHU_DELIVERY_PROFILE;
              }),
          },
          {
            name: 'feishu-member-authorization',
            run: () =>
              loadFeishuMemberAuthorizationBlock({ transition: transitionToken }).catch(() => {
                if (shouldApplyWorkspaceLoad(transitionToken)) setFeishuMemberAuthorizationState(DEFAULT_FEISHU_MEMBER_AUTHORIZATION);
                return DEFAULT_FEISHU_MEMBER_AUTHORIZATION;
              }),
          },
          {
            name: nextAuth.user?.primaryRole === 'admin'
              ? 'system-admin-settings'
              : 'organization-model-profile',
            run: () => {
              if (nextAuth.user?.primaryRole === 'admin') {
                return loadSystemAdminSettingsBlock(nextAuth.sessionMode === 'cloud', { transition: transitionToken });
              }
              // 组织模型的管理资料不是普通成员启动桌面的必要条件。旧接口在未配置或
              // 无读取资格时会返回 403/404，不能把它误报成 admin-setting 加载失败。
              // 普通成员继续使用已经同步完成的组织 AI 运行配置；管理资料保持空投影。
              return loadOrgModelBlock({ transition: transitionToken }).catch((error) => {
                console.info('[bootstrap] optional organization model profile unavailable for non-admin', error);
                if (shouldApplyWorkspaceLoad(transitionToken)) setOrgModelState(EMPTY_ORG_MODEL_SETTINGS);
                return EMPTY_ORG_MODEL_SETTINGS;
              });
            },
          },
        ];
        markWorkspaceRuntime('switching', `正在加载 ${loadedActiveWorkspace?.name || '当前组织'} 的客户、任务、事件线和设置…`);
        let completedCount = 0;
        const totalCount = backgroundLoaders.length;
        const failedBackgroundBlocks = (
          await Promise.all(
            backgroundLoaders.map(async ({ name, run }) => {
              try {
                await run();
                console.info(`[bootstrap] ${name} loaded`);
                return null;
              } catch (error) {
                console.error(`[bootstrap] ${name} failed`, error);
                return name;
              } finally {
                completedCount += 1;
                if (shouldApplyWorkspaceLoad(transitionToken)) {
                  setLoadingSubProgress(Math.round((completedCount / totalCount) * 100));
                }
              }
            }),
          )
        ).filter((item): item is string => Boolean(item));
        if (!shouldApplyWorkspaceLoad(transitionToken)) return;
        setLoadingSubProgress(0);
        if (nextAuth.user?.primaryRole !== 'admin') {
          setAgentWorklogs([]);
          setAgentWeeklyDigests([]);
          setAgentWeeklyPlans([]);
        }
        markLoadingPhase('正在载入客户工作区…');
        await loadClientBlock(nextClientId, {
          transition: transitionToken,
          organizationId: nextAuth.user?.organizationId,
        });
        if (!shouldApplyWorkspaceLoad(transitionToken)) return;
        if (failedBackgroundBlocks.length > 0) {
          flash('error', `部分模块加载失败：${failedBackgroundBlocks.join('、')}`);
        }
        setSettingsSectionLoaded({
          overview: true,
          account: false,
          tasks: true,
          client_workspace: false,
          topics: false,
          handbook: false,
          system_admin: false,
          org_overview: false,
          org_departments: false,
          org_people: false,
          org_rules: false,
          system_logs: false,
          about: false,
        });
        if (nextAuth.user?.primaryRole === 'admin') {
          markLoadingPhase('正在读取员工与组织数据…');
          await loadEmployeeReviewBlock({ transition: transitionToken });
        } else {
          setEmployeeReviews([]);
        }
        if (shouldApplyWorkspaceLoad(transitionToken)) {
          await refreshCurrentWorkspaceRuntime(nextAuth, transitionToken, 'load-all-org-complete');
        }
      } else {
        markLoadingPhase('正在切换到登录态…');
        setClients([]);
        setWorkspace(null);
        setTasks([]);
        setTaskLists([]);
        setTaskTags([]);
        setTaskSettingsState(null);
        setOrgModelState(EMPTY_ORG_MODEL_SETTINGS);
        setAgentWorklogs([]);
        setAgentWeeklyDigests([]);
        setAgentWeeklyPlans([]);
        setReviewDashboard(null);
        setRadars([]);
        setCandidates([]);
        setIntelligenceProfiles([]);
        setHandbookEntries([]);
        setLogs([]);
        setEmployeeReviews([]);
        setClientWorkspaceSettingsState(DEFAULT_CLIENT_WORKSPACE_SETTINGS);
        setTopicsSettingsState(DEFAULT_TOPICS_SETTINGS);
        setHandbookSettingsState(DEFAULT_HANDBOOK_SETTINGS);
        setSystemAdminSettingsState(DEFAULT_SYSTEM_ADMIN_SETTINGS);
        setOrgMembershipState(DEFAULT_ORG_MEMBERSHIP_SUMMARY);
        setOrgAdminClaimStatus(DEFAULT_ORG_ADMIN_CLAIM_STATUS);
        setOrgFeishuIntegrationState(DEFAULT_ORG_FEISHU_INTEGRATION);
        setFeishuDeliveryProfileState(DEFAULT_FEISHU_DELIVERY_PROFILE);
        setFeishuMemberAuthorizationState(DEFAULT_FEISHU_MEMBER_AUTHORIZATION);
        feishuStatusHydrationInFlightRef.current = false;
        feishuTaskSyncReadinessInFlightRef.current = false;
        setFeishuTaskSyncReadiness(DEFAULT_FEISHU_TASK_SYNC_READINESS);
        setOrgFeishuIntegrationLoaded(false);
        setFeishuDeliveryProfileLoaded(false);
        setFeishuMemberAuthorizationLoaded(false);
        setFeishuAuthorizationBusyAction('idle');
        setFeishuAuthorizationFlowState(null);
        setSettingsSectionLoaded({
          overview: true,
          account: false,
          tasks: true,
          client_workspace: false,
          topics: false,
          handbook: false,
          system_admin: false,
          org_overview: false,
          org_departments: false,
          org_people: false,
          org_rules: false,
          system_logs: false,
          about: false,
        });
        markWorkspaceRuntime('local_draft', runtime.message || '尚未登录组织；本机隔离区不会作为工作空间显示。');
      }
      // 组织计划在启动并发阶段可能先于最终 workspace/auth 结算返回，随后又被
      // 同一启动流程的业务态清理作废。启动终态形成后再串行读取一次，保证首次
      // 打开计划页就有部门、周期和行动，而不是只能靠切页/HMR碰巧恢复。
      if (
        hasCompleteSessionIdentity(nextAuth)
        && shouldApplyWorkspaceLoad(transitionToken)
      ) {
        await loadOrganizationPlanningBlock({
          transition: transitionToken,
          organizationId: nextAuth.user?.organizationId,
        });
      }
      startupRetryRef.current = 0;
      clearLocalServiceStartupBanner();
      markLoadingPhase('启动完成');
    } catch (error) {
      if (!shouldApplyWorkspaceLoad(transitionToken)) return;
      const message = error instanceof Error ? error.message : '加载失败';
      markLoadingPhase(`启动受阻：${message}`);
      const allowStartupRetry = options?.allowStartupRetry ?? true;
      if (allowStartupRetry && isLocalServiceStartupError(error) && startupRetryRef.current < 2) {
        startupRetryRef.current += 1;
        keepLoadingForRetry = true;
        window.setTimeout(() => {
          void loadAll(nextClientId, { allowStartupRetry: true });
        }, 1200);
      } else {
        flash('error', message);
      }
    } finally {
      if (!keepLoadingForRetry && shouldApplyWorkspaceLoad(transitionToken)) {
        if (WORKSPACE_BUSY_RUNTIME_STATUSES.has(workspaceRuntimeStatusRef.current)) {
          await refreshCurrentWorkspaceRuntime(latestAuthForRuntime || authState, transitionToken, 'load-all-final-busy-state');
        }
        setLoading(false);
      }
      loadAllInFlightRef.current = false;
    }
  }

  async function handleLogoutFromUi() {
    try {
      const response = await logout();
      // Logout is an authorization boundary, not a normal background refresh.
      // Clear organization projections synchronously so stale React closures or
      // an in-flight bootstrap cannot keep private data visible after logout.
      beginWorkspaceTransition('switching', '正在清理已退出组织的界面数据…', {
        sandboxId: activeSandboxIdRef.current || workspacesState?.activeSandboxId || '',
        reason: 'logout',
      });
      resetFeishuWorkspaceTransientState();
      resetBusinessWorkspaceTransientState();
      setAuthState(response);
      setWorkspaceManagerOpen(false);
      markWorkspaceRuntime('needs_login', '已退出组织，请重新登录后继续。');
      await loadAll(undefined, { allowStartupRetry: false });
    } catch (error) {
      flash('error', error instanceof Error ? error.message : '退出失败');
    }
  }

  const normalizeCloudAuthSubmitError = (error: unknown): string => {
    const message = error instanceof Error ? error.message : String(error || '');
    if (/已有组织管理员|组织已存在管理员|已有管理员/.test(message)) {
      return '这个云端已经有管理员，不能直接接管。请联系管理员生成组织或部门邀请码，然后选择「加入组织」进入。';
    }
    if (/JSONDecodeError|Unexpected token|Unexpected end of JSON|Expecting value/i.test(message)) {
      return '云地址返回的不是组织云 API 数据。请确认填写的是组织云端地址，并且云服务已经部署完成。';
    }
    if (/Cloud backend unavailable|circuit breaker/i.test(message)) {
      return '暂时连不上组织云。请检查云地址和网络，稍后重试；登录、加入和创建组织不会被这次失败永久锁住。';
    }
    return message || '提交失败';
  };

  const handleCloudAuthSubmit = async () => {
    setCloudAuthSubmitting(true);
    setCloudAuthMessage('');
    try {
      const cloudApiUrl = cloudApiUrlFromHost(cloudAuthForm.cloudApiUrl);
      if (!cloudApiUrl) {
        throw new Error('请填写组织云端地址。');
      }
      if (cloudAuthAction === 'login') {
        const identifier = cloudAuthForm.identifier.trim();
        if (!identifier) {
          throw new Error('请填写手机号或邮箱。');
        }
        const response = await login({
          cloudApiUrl,
          identifier,
          password: cloudAuthForm.password,
          rememberMe: cloudAuthForm.rememberMe,
        });
        if (response.organizationSelectionRequired) {
          setOrganizationSelection({
            token: response.organizationSelectionToken || '',
            organizations: response.organizations || [],
          });
          setCloudAuthMessage(response.message || '请选择要进入的组织工作空间。');
          return;
        }
        setAuthState(response);
      } else if (cloudAuthAction === 'join') {
        const inviteCode = normalizeDepartmentInviteInput(cloudAuthForm.inviteCode);
        const fullName = sanitizePersonNameInput(cloudAuthForm.fullName);
        if (!inviteCode) {
          throw new Error('加入组织需要填写组织或部门邀请码。');
        }
        const joiningWithCurrentCloudSession = isCloudSession && activeWorkspaceMatchesCloudUrl(cloudApiUrl);
        if (!joiningWithCurrentCloudSession) {
          if (!fullName) {
            throw new Error('请填写称呼。');
          }
          if (!cloudAuthForm.phone.trim()) {
            throw new Error('请填写手机号，建议填写飞书账号绑定手机号。');
          }
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cloudAuthForm.email.trim())) {
            throw new Error('请填写有效邮箱。');
          }
          if (cloudAuthForm.password.length < 8) {
            throw new Error('请设置至少 8 位密码。');
          }
        }
        const response = joiningWithCurrentCloudSession
          ? await joinOrganization({
            cloudApiUrl,
            inviteCode,
            departmentId: cloudAuthForm.departmentId || null,
            jobTitle: cloudAuthForm.jobTitle || null,
            managerName: cloudAuthForm.managerName || null,
            currentFocus: cloudAuthForm.currentFocus || null,
          })
          : await register({
            cloudApiUrl,
            email: cloudAuthForm.email,
            phone: cloudAuthForm.phone.trim(),
            fullName,
            password: cloudAuthForm.password,
            inviteCode,
            departmentId: cloudAuthForm.departmentId || null,
            jobTitle: cloudAuthForm.jobTitle || null,
            managerName: cloudAuthForm.managerName || null,
            currentFocus: cloudAuthForm.currentFocus || null,
          });
        if (response.organizationSelectionRequired) {
          setOrganizationSelection({
            token: response.organizationSelectionToken || '',
            organizations: response.organizations || [],
          });
          setCloudAuthMessage(response.message || '请选择要进入的组织工作空间。');
          return;
        }
        setAuthState(response);
      } else {
        const organizationName = cloudAuthForm.organizationName.trim();
        const fullName = sanitizePersonNameInput(cloudAuthForm.fullName);
        const response = isCloudSession && activeWorkspaceMatchesCloudUrl(cloudApiUrl)
          ? await createOrganization({ cloudApiUrl, organizationName: organizationName || `${fullName || '新组织'}的组织` })
          : await register({
            cloudApiUrl,
            email: cloudAuthForm.email,
            phone: cloudAuthForm.phone.trim(),
            fullName,
            password: cloudAuthForm.password,
            organizationName: organizationName || null,
            inviteCode: null,
            departmentId: null,
            jobTitle: null,
            managerName: null,
            currentFocus: null,
          });
        if (response.organizationSelectionRequired) {
          setOrganizationSelection({
            token: response.organizationSelectionToken || '',
            organizations: response.organizations || [],
          });
          setCloudAuthMessage(response.message || '请选择要进入的组织工作空间。');
          return;
        }
        setAuthState(response);
      }
      try {
        const rememberedIdentifier = cloudAuthAction === 'login'
          ? cloudAuthForm.identifier.trim()
          : (cloudAuthForm.email || cloudAuthForm.phone).trim();
        const nextLocalInputMemory = await saveCloudAuthInputMemory({
          rememberInputs: cloudAuthForm.rememberInputs,
          email: cloudAuthForm.email,
          identifier: rememberedIdentifier || cloudAuthForm.email,
          fullName: cloudAuthForm.fullName,
          password: cloudAuthForm.password,
        });
        setLocalInputMemoryState(nextLocalInputMemory);
      } catch (memoryError) {
        console.warn('[cloud-auth] save local input memory failed', memoryError);
      }
      const authenticatedWorkspaces = await getWorkspaces();
      await refreshWorkspaceAwareState(authenticatedWorkspaces);
      setCloudAuthForm({
        cloudApiUrl: '',
        organizationName: '',
        email: '',
        identifier: '',
        phone: '',
        fullName: '',
        password: '',
        confirmPassword: '',
        inviteCode: '',
        departmentId: '',
        jobTitle: '',
        managerName: '',
        currentFocus: '',
        rememberMe: true,
        rememberInputs: localInputMemoryState.cloudAuth.rememberInputs,
      });
      setCloudAuthMessage('');
      setCloudAuthModalOpen(false);
    } catch (error) {
      setCloudAuthMessage(normalizeCloudAuthSubmitError(error));
    } finally {
      setCloudAuthSubmitting(false);
    }
  };

  useEffect(() => {
    if (!hasAuthenticatedSession) {
      setDepartmentOptions([]);
      return;
    }
    void loadDepartmentOptionsBlock(currentSessionUser?.organizationId ?? null).catch(() => undefined);
  }, [currentSessionUser?.organizationId, hasAuthenticatedSession]);

  useEffect(() => {
    // 计划页本身就是当前可见实例的最终只读消费者，不能因为启动状态仍被标为
    // verifying/switching 就跳过加载；旧实例和跨 sandbox 回包由 mounted + request
    // generation 门禁淘汰。否则界面已可操作却永久只剩“当前组织”空壳。
    if (!hasAuthenticatedSession || taskViewMode !== 'plan') return;
    void loadOrganizationPlanningBlock({
      organizationId: currentSessionUser?.organizationId ?? null,
    }).catch((error) => {
      console.warn('[organization-planning] plan workspace refresh failed', error);
    });
  }, [
    currentSessionUser?.organizationId,
    hasAuthenticatedSession,
    taskViewMode,
    workspacesState?.activeSandboxId,
  ]);

  useEffect(() => {
    if (!isCloudSession) return;
    setCloudAuthModalOpen(false);
    setCloudAuthMessage('');
    setCloudAuthForm({
      cloudApiUrl: '',
      organizationName: '',
      email: '',
      identifier: '',
      phone: '',
      fullName: '',
      password: '',
      confirmPassword: '',
      inviteCode: '',
      departmentId: '',
      jobTitle: '',
      managerName: '',
      currentFocus: '',
      rememberMe: true,
      rememberInputs: localInputMemoryState.cloudAuth.rememberInputs,
    });
  }, [isCloudSession]);

  const refreshDesktopAppInfo = useCallback(async () => {
    const nextInfo = await window.yiyuWorkbench.getDesktopAppInfo();
    setDesktopAppInfo(nextInfo);
    return nextInfo;
  }, []);

  useEffect(() => {
    void refreshDesktopAppInfo().catch(() => undefined);
    const handleFocus = () => { void refreshDesktopAppInfo().catch(() => undefined); };
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        void refreshDesktopAppInfo().catch(() => undefined);
      }
    };
    const intervalId = window.setInterval(() => {
      if (document.visibilityState === 'visible') {
        void refreshDesktopAppInfo().catch(() => undefined);
      }
    }, 15000);
    window.addEventListener('focus', handleFocus);
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      window.removeEventListener('focus', handleFocus);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.clearInterval(intervalId);
    };
  }, [refreshDesktopAppInfo]);

  useEffect(() => {
    void getSourceIntegrity(undefined, {
      frontendBuildVersion: desktopAppInfo?.frontendBuildVersion ?? null,
      frontendGitCommit: desktopAppInfo?.frontendGitCommit ?? null,
    }).then(setWorkspaceSourceIntegrity).catch(() => undefined);
  }, [desktopAppInfo?.frontendBuildVersion, desktopAppInfo?.frontendGitCommit]);

  // P0-1: task board 自动刷新 ——
  // 旧行为：startup 拉一次 task board，之后只在用户主动触发（建任务/录音完成等）时刷。
  //         手机端建的任务推到 cloud → desktop backend 后，desktop UI 永远不知道，得 Cmd+R 才能看到。
  // 新行为：30s polling + 窗口聚焦/可见时立刻刷一次。loadTaskBlock 内部已有 optimistic 去重，重复拉安全。
  // 用 ref 锁定最新版 loadTaskBlock（避免每次 render 重建 effect）。
  const loadTaskBlockRef = useRef(loadTaskBlock);
  loadTaskBlockRef.current = loadTaskBlock;
  useEffect(() => {
    const refresh = () => {
      if (document.visibilityState !== 'visible') return;
      void loadTaskBlockRef.current().catch(() => undefined);
    };
    const intervalId = window.setInterval(refresh, 30000);
    const handleFocus = () => refresh();
    const handleVisibilityChange = () => refresh();
    window.addEventListener('focus', handleFocus);
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      window.clearInterval(intervalId);
      window.removeEventListener('focus', handleFocus);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  // S4.5: workspace 结构变化的启发式判断, 替代 JSON.stringify 几百 KB 对象的深比较 (Electron 卡顿元凶).
  // 策略: 比 26 个核心 list length + 几个 scalar + nested 关键字段.
  // Trade-off: 接受少数 false negative (e.g. 改 doc 内容但 count 一致 → UI 不刷新),
  // 因为产品里改内容通常涉及 count/version 变化, 这种情况极罕见.
  function isWorkspaceStructurallyUnchanged(prev: any, next: any): boolean {
    if (prev === next) return true;
    if (!prev || !next) return false;
    if (prev.client?.id !== next.client?.id) return false;
    const LIST_KEYS = [
      'folders', 'documents', 'documentCards', 'imports', 'knowledgeJobs',
      'recentReclassEvents', 'memoryCards', 'threads', 'recentMessages',
      'analysisRuns', 'meetings', 'goals', 'dnaModules', 'projectModules',
      'projectFlows', 'dnaTerms', 'relatedTasks', 'latestJudgments',
      'latestTopics', 'latestConflicts', 'latestOpenQuestions', 'latestRunLogs',
    ];
    for (const key of LIST_KEYS) {
      const a = prev[key];
      const b = next[key];
      const al = Array.isArray(a) ? a.length : 0;
      const bl = Array.isArray(b) ? b.length : 0;
      if (al !== bl) return false;
    }
    const previousProcessing = (prev.documents || [])
      .map((item: any) => [
        item.id,
        item.parseStatus,
        item.wikiStatus,
        item.sharedSummaryState,
        item.sharedSummaryUpdatedAt,
        item.processingAttemptNo,
        item.processingErrorCode,
      ].join(':'))
      .join('|');
    const nextProcessing = (next.documents || [])
      .map((item: any) => [
        item.id,
        item.parseStatus,
        item.wikiStatus,
        item.sharedSummaryState,
        item.sharedSummaryUpdatedAt,
        item.processingAttemptNo,
        item.processingErrorCode,
      ].join(':'))
      .join('|');
    if (previousProcessing !== nextProcessing) return false;
    if (prev.surrogateCount !== next.surrogateCount) return false;
    if (prev.memoryDocCount !== next.memoryDocCount) return false;
    if (prev.knowledgeStatus?.lastIndexedAt !== next.knowledgeStatus?.lastIndexedAt) return false;
    if (prev.knowledgeStatus?.totalDocs !== next.knowledgeStatus?.totalDocs) return false;
    if (prev.knowledgeStatus?.pendingDocs !== next.knowledgeStatus?.pendingDocs) return false;
    if (prev.knowledgeStatus?.totalDocuments !== next.knowledgeStatus?.totalDocuments) return false;
    if (prev.knowledgeStatus?.pendingJobs !== next.knowledgeStatus?.pendingJobs) return false;
    if (prev.knowledgeStatus?.runningJobs !== next.knowledgeStatus?.runningJobs) return false;
    if (prev.knowledgeStatus?.lastJobStatus !== next.knowledgeStatus?.lastJobStatus) return false;
    if (prev.knowledgeStatus?.lastJobError !== next.knowledgeStatus?.lastJobError) return false;
    // 关键 nested ID 字段
    if (prev.notebookSummary?.updatedAt !== next.notebookSummary?.updatedAt) return false;
    if (prev.latestContextPack?.id !== next.latestContextPack?.id) return false;
    if (prev.judgmentBundle?.updatedAt !== next.judgmentBundle?.updatedAt) return false;
    if (prev.knowledgeContext?.state?.overall !== next.knowledgeContext?.state?.overall) return false;
    if (prev.knowledgeContext?.state?.organizationShared !== next.knowledgeContext?.state?.organizationShared) return false;
    if (prev.knowledgeContext?.state?.localPrivate !== next.knowledgeContext?.state?.localPrivate) return false;
    if (prev.knowledgeContext?.counts?.organizationShared !== next.knowledgeContext?.counts?.organizationShared) return false;
    if (prev.knowledgeContext?.counts?.localPrivate !== next.knowledgeContext?.counts?.localPrivate) return false;
    return true;
  }

  async function refreshWorkspace(clientId?: string) {
    const targetClientId = clientId ?? currentClientId;
    if (!targetClientId) return;
    const startedSandboxId = currentActiveSandboxId();
    const token = workspaceLoadGateRef.current.begin(scopedAsyncKey(
      startedSandboxId,
      authState.user?.organizationId,
      targetClientId,
    ));
    const nextWorkspace = await getClientWorkspace(targetClientId);
    if (
      !workspaceLoadGateRef.current.accepts(token)
      || !shouldApplyWorkspaceLoad(null, startedSandboxId)
      || currentClientIdRef.current !== targetClientId
    ) return;
    setWorkspace((prev) => {
      if (!prev) return nextWorkspace;
      // S4.5 fix: 用关键字段集启发式比较, 不再 JSON.stringify 30+ 字段几百 KB 的对象 — Electron 卡顿元凶
      if (isWorkspaceStructurallyUnchanged(prev, nextWorkspace)) return prev;
      return nextWorkspace;
    });
    void loadClientPageContextBlock(targetClientId);
    void loadWorkspacePersistedProposalDraftsBlock(targetClientId);
    void loadProposalBlock(targetClientId);
    return nextWorkspace;
  }

  useEffect(() => {
    // Startup/workspace switching already owns a scoped workspace request. Starting an
    // unscoped refresh here would advance the request gate, discard the correct startup
    // response, and then discard itself because the transition is still busy. Wait until
    // the transition settles; the status dependency below then performs one fresh read.
    if (
      activeTab !== 'client_workspace'
      || !currentClientId
      || loading
      || WORKSPACE_BUSY_RUNTIME_STATUSES.has(workspaceRuntimeStatus)
    ) return;
    void refreshWorkspace(currentClientId).catch((error) => {
      console.warn(
        '[workspace] current project refresh deferred',
        error instanceof Error ? error.message : String(error),
      );
    });
  }, [
    activeTab,
    authState.user?.organizationId,
    currentClientId,
    loading,
    workspaceRuntimeStatus,
    workspacesState?.activeSandboxId,
  ]);

  const projectMaterialProcessingKeysRef = useRef(new Set<string>());
  useEffect(() => {
    if (activeTab !== 'client_workspace' || !currentClientId || !workspace) return;
    if (workspace.client?.id !== currentClientId) return;
    const pending = (workspace.documents || []).filter(
      (document) => (
        !document.parseStatus
        || document.parseStatus === 'not_requested'
        || (
          document.parseStatus === 'ready'
          && (!document.wikiStatus || ['not_requested', 'queued'].includes(document.wikiStatus))
        )
        || (
          document.parseStatus === 'ready'
          && (!document.sharedSummaryState || document.sharedSummaryState === 'not_requested')
        )
      ),
    );
    if (pending.length === 0) return;
    const startedSandboxId = currentActiveSandboxId();
    const key = [
      startedSandboxId,
      currentClientId,
      ...pending.map((document) => document.id).sort(),
    ].join(':');
    if (projectMaterialProcessingKeysRef.current.has(key)) return;
    projectMaterialProcessingKeysRef.current.add(key);
    void processPendingProjectMaterials(currentClientId, {
      documentIds: pending.map((document) => document.id),
    }).then((result) => {
      if ((result.sharedSummaries?.ready || 0) > 0) {
        writeRuntimeUiSessionValue(
          [
            'workspace-knowledge-presentation',
            startedSandboxId || 'local',
            currentClientId,
          ].join(':'),
          null,
        );
        markClientKnowledgeChanged(currentClientId, 'material_imported');
      }
      if (
        shouldApplyWorkspaceLoad(null, startedSandboxId)
        && currentClientIdRef.current === currentClientId
      ) {
        void refreshWorkspace(currentClientId).catch(() => undefined);
      }
    }).catch((error) => {
      console.warn(
        '[project-materials] processing trigger failed',
        error instanceof Error ? error.message : String(error),
      );
    }).finally(() => {
      // A transient backend/cloud failure must not permanently suppress this
      // exact document set.  The next explicit refresh may retry it.
      projectMaterialProcessingKeysRef.current.delete(key);
    });
  }, [
    activeTab,
    currentClientId,
    workspace,
    workspacesState?.activeSandboxId,
  ]);

  const mobileLinkTransferProcessingRef = useRef(new Set<string>());
  useEffect(() => {
    if (
      activeTab !== 'client_workspace'
      || !currentClientId
      || !workspace
      || workspace.client?.id !== currentClientId
      || authState.sessionMode !== 'cloud'
    ) return;
    let disposed = false;
    const processNext = async () => {
      if (disposed) return;
      const pending = await listPendingMobileLinkTransfers(currentClientId);
      const transfer = pending.find(
        (item) => !mobileLinkTransferProcessingRef.current.has(item.runId),
      );
      if (!transfer || disposed) return;
      mobileLinkTransferProcessingRef.current.add(transfer.runId);
      try {
        await claimMobileLinkTransfer(currentClientId, transfer.runId);
        const localRun = await startClientLinkMaterialImport(
          currentClientId,
          transfer.sourceUrl,
          {
            useBrowserCookies: false,
            idempotencyKey: `mobile-link-transfer:${transfer.runId}`,
          },
        );
        if (localRun.status === 'completed' && localRun.documentId) {
          await settleMobileLinkTransfer(currentClientId, transfer.runId, {
            status: 'completed',
            title: localRun.title || undefined,
            documentId: localRun.documentId,
          });
          markClientKnowledgeChanged(currentClientId, 'material_imported');
          await refreshWorkspace(currentClientId);
        } else {
          await settleMobileLinkTransfer(currentClientId, transfer.runId, {
            status: /暂不支持|登录|Cookie|权限/i.test(localRun.error || '')
              ? 'blocked'
              : 'failed_retryable',
            title: localRun.title || undefined,
            error: localRun.error || '当前设备未能完成链接转存',
          });
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        try {
          await settleMobileLinkTransfer(currentClientId, transfer.runId, {
            status: /暂不支持|登录|Cookie|权限/i.test(message)
              ? 'blocked'
              : 'failed_retryable',
            error: message,
          });
        } catch (settlementError) {
          console.warn('[mobile-link-transfer] settlement failed', settlementError);
        }
      } finally {
        mobileLinkTransferProcessingRef.current.delete(transfer.runId);
      }
    };
    void processNext().catch((error) => {
      console.warn('[mobile-link-transfer] intake check failed', error);
    });
    const timer = window.setInterval(() => {
      void processNext().catch((error) => {
        console.warn('[mobile-link-transfer] intake check failed', error);
      });
    }, 10_000);
    return () => {
      disposed = true;
      window.clearInterval(timer);
    };
  }, [
    activeTab,
    authState.sessionMode,
    currentClientId,
    workspace?.client?.id,
    workspacesState?.activeSandboxId,
  ]);

  function applyWorkspaceKnowledgeProgress(progress: Awaited<ReturnType<typeof getClientKnowledgeProgress>>, startedSandboxId = currentActiveSandboxId()) {
    if (!shouldApplyWorkspaceLoad(null, startedSandboxId)) return;
    setWorkspace((prev) => {
      if (!prev) return prev;
      const nextStatus = progress.knowledgeStatus;
      const nextJobs = progress.knowledgeJobs || [];
      // S4.5 fix: 字段级比较代替 JSON.stringify
      const prevStatus = prev.knowledgeStatus || null;
      const statusUnchanged =
        prevStatus === nextStatus ||
        (
          !!prevStatus && !!nextStatus &&
          (prevStatus as any).status === (nextStatus as any).status &&
          (prevStatus as any).totalDocs === (nextStatus as any).totalDocs &&
          (prevStatus as any).pendingDocs === (nextStatus as any).pendingDocs &&
          (prevStatus as any).totalDocuments === (nextStatus as any).totalDocuments &&
          (prevStatus as any).pendingJobs === (nextStatus as any).pendingJobs &&
          (prevStatus as any).runningJobs === (nextStatus as any).runningJobs &&
          (prevStatus as any).lastJobStatus === (nextStatus as any).lastJobStatus &&
          (prevStatus as any).lastJobError === (nextStatus as any).lastJobError &&
          (prevStatus as any).lastIndexedAt === (nextStatus as any).lastIndexedAt
        ) ||
        (!prevStatus && !nextStatus);
      const prevJobs = prev.knowledgeJobs || [];
      const jobsUnchanged =
        prevJobs.length === nextJobs.length &&
        (prevJobs.length === 0 ||
          ((prevJobs[0] as any)?.id === (nextJobs[0] as any)?.id &&
           (prevJobs[prevJobs.length - 1] as any)?.id === (nextJobs[nextJobs.length - 1] as any)?.id &&
           (prevJobs[0] as any)?.status === (nextJobs[0] as any)?.status &&
           (prevJobs[0] as any)?.processedItems === (nextJobs[0] as any)?.processedItems &&
           (prevJobs[0] as any)?.totalItems === (nextJobs[0] as any)?.totalItems &&
           (prevJobs[0] as any)?.currentItemLabel === (nextJobs[0] as any)?.currentItemLabel &&
           (prevJobs[0] as any)?.lastEventMessage === (nextJobs[0] as any)?.lastEventMessage));
      if (statusUnchanged && jobsUnchanged) return prev;
      return {
        ...prev,
        knowledgeStatus: nextStatus,
        knowledgeJobs: nextJobs,
      };
    });
  }

  useEffect(() => {
    if (!currentClientId) {
      setWorkspacePageContext(null);
      setWorkspacePersistedProposalDrafts([]);
      setWorkspacePersistedProposalDraftsError(null);
      return;
    }
    void loadClientPageContextBlock(currentClientId);
    void loadWorkspacePersistedProposalDraftsBlock(currentClientId);
  }, [currentClientId]);

  const requestGrowthContextJump = (context: GrowthContextLink) => {
    const normalizedTab = (context.tab === 'growth' ? 'growth_handbook' : context.tab) as NavKey | string;
    if (
      normalizedTab === 'tasks'
      || normalizedTab === 'client_workspace'
      || normalizedTab === 'strategic_accompaniment'
      || normalizedTab === 'topics_management'
      || normalizedTab === 'growth_handbook'
      || normalizedTab === 'settings'
    ) {
      setActiveTab(normalizedTab as NavKey);
    }
    setGrowthContextJump({ requestId: createUiId('growth-context'), context });
  };

  const consumeGrowthContextJump = (requestId: string) => {
    setGrowthContextJump((prev) => (prev?.requestId === requestId ? null : prev));
  };

  const workspaceKnowledgeActiveRef = useRef(false);
  workspaceKnowledgeActiveRef.current =
    ((workspace?.knowledgeStatus?.pendingJobs || 0) + (workspace?.knowledgeStatus?.runningJobs || 0)) > 0;

  useEffect(() => {
    const targetClientId = currentClientId;
    const startedSandboxId = currentActiveSandboxId();
    if (!targetClientId) {
      setIsImportSubmitting(false);
      return;
    }
    if (!isImportSubmitting && !workspaceKnowledgeActiveRef.current) return;
    let cancelled = false;
    let polling = false;
    let finalRefreshQueued = false;
    const pollKnowledgeProgress = async () => {
      if (polling) return;
      polling = true;
      try {
        const progress = await getClientKnowledgeProgress(targetClientId);
        if (cancelled) return;
        applyWorkspaceKnowledgeProgress(progress, startedSandboxId);
        const nextStatus = progress.knowledgeStatus;
        const nextActiveJobs = (nextStatus?.pendingJobs || 0) + (nextStatus?.runningJobs || 0);
        if (nextActiveJobs === 0 && !finalRefreshQueued && Date.now() >= importProgressHoldUntilRef.current) {
          finalRefreshQueued = true;
          setIsImportSubmitting(false);
          void refreshWorkspace(targetClientId).catch(() => undefined);
        }
      } catch {
        if (!cancelled && Date.now() >= importProgressHoldUntilRef.current) {
          setIsImportSubmitting(false);
        }
      } finally {
        polling = false;
      }
    };
    void pollKnowledgeProgress();
    const timer = window.setInterval(() => {
      void pollKnowledgeProgress();
    }, 1500);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, [
    currentClientId,
    isImportSubmitting,
  ]);

  useEffect(() => {
    // A deep link may provide only an opaque client_id. Never resolve names from the URL.
    void loadAll(initialNavigationStateRef.current?.evidenceClientId || undefined);
  }, []);

  useEffect(() => {
    if (!hasAuthenticatedSession || !isCloudSession) return undefined;
    let cancelled = false;

    const run = async () => {
      if (consultationKnowledgeSyncInFlightRef.current) return;
      consultationKnowledgeSyncInFlightRef.current = true;
      const targetClientId = currentClientId;
      const startedSandboxId = currentActiveSandboxId();
      try {
        const summary = await processPendingConsultationKnowledgeRequests();
        if (cancelled || !shouldApplyWorkspaceLoad(null, startedSandboxId)) return;
        if (summary.failedCount > 0) {
          console.warn(
            '[consultation-knowledge] pending sync completed with failures',
            {
              processedCount: summary.processedCount,
              completedCount: summary.completedCount,
              failedCount: summary.failedCount,
              failures: summary.items
                .filter((item) => item.status === 'failed')
                .map((item) => ({
                  requestId: item.id,
                  clientId: item.clientId || null,
                  errorMessage: item.errorMessage || null,
                })),
            },
          );
        } else if (summary.processedCount > 0) {
          console.info(
            `[consultation-knowledge] processed=${summary.processedCount} completed=${summary.completedCount}`,
          );
        }
        const touchedCurrentClient = Boolean(
          targetClientId
          && summary.items.some((item) => item.clientId === targetClientId),
        );
        if (touchedCurrentClient) {
          await refreshWorkspace(targetClientId);
        }
      } catch (error) {
        if (!cancelled) {
          console.warn('[consultation-knowledge] pending sync failed', error);
        }
      } finally {
        consultationKnowledgeSyncInFlightRef.current = false;
      }
    };

    void run();
    const timer = window.setInterval(() => {
      void run();
    }, 60_000);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, [
    hasAuthenticatedSession,
    isCloudSession,
    currentClientId,
    currentSessionUser?.id,
    currentSessionUser?.organizationId,
    workspacesState?.activeSandboxId,
  ]);

  useEffect(() => {
    if (taskViewMode === 'agent_schedule') {
      setTaskViewMode('calendar');
    }
  }, [taskViewMode]);

  useEffect(() => {
    if (activeTab !== 'tasks' || !hasAuthenticatedSession || currentSessionUser?.primaryRole !== 'admin') return;
    void loadAgentWorklogBlock(taskCalendarMonthLabel).catch(() => {
      setAgentWorklogs([]);
      setAgentWeeklyDigests([]);
      setAgentWeeklyPlans([]);
    });
  }, [activeTab, hasAuthenticatedSession, currentSessionUser?.primaryRole, taskCalendarMonthLabel]);

  useEffect(() => {
    if (activeTab !== 'settings' || !hasAuthenticatedSession) return;
    void loadSettingsSectionBlock(settingsSection).catch((error) => {
      flash('error', error instanceof Error ? error.message : '系统设置加载失败');
    });
  }, [activeTab, settingsSection, hasAuthenticatedSession]);

    const activeTaskLists = useMemo(
      () => dedupeTaskListsForDisplay(taskLists.filter((item) => !item.archivedAt)),
      [taskLists],
    );
    const orgTaskLists = useMemo(
      () => activeTaskLists.filter((item) => (item.scope || 'org') === 'org'),
      [activeTaskLists],
    );
    const taskDefaultDestinationLists = useMemo(
      () => getTaskDefaultDestinationLists(activeTaskLists),
      [activeTaskLists],
    );
    const personalTaskLists = useMemo(
      () => activeTaskLists.filter((item) => (item.scope || 'org') === 'personal'),
      [activeTaskLists],
    );
    const resolveDefaultListId = (scope: 'org' | 'personal') => {
      const listPool = scope === 'personal' ? personalTaskLists : orgTaskLists;
      return listPool.find((item) => item.isDefault)?.id || listPool[0]?.id || '';
    };
  const activeTaskTags = useMemo(
    () => taskTags.filter((item) => !item.archivedAt),
    [taskTags],
  );

  useEffect(() => {
    window.localStorage.setItem('yiyu-sidebar-collapsed', isSidebarCollapsed ? '1' : '0');
  }, [isSidebarCollapsed]);

  useEffect(() => {
    if (canUseCollabSync) return;
    setMaintenanceModeStatus(null);
    setMaintenanceModeError(null);
    setIsMaintenanceModeLoading(false);
    setMaintenanceModeBusyAction(null);
    setCollabStatus(null);
    setIsCollabStatusLoading(false);
    setCollabBusyAction(null);
    setCollabDialogState(null);
    setCollabSelectedPaths([]);
    setCollabCommitMessage('');
    setCollabDialogError(null);
  }, [canUseCollabSync]);

  useEffect(() => {
    if (!canShowMaintenanceSyncPanel) {
      setMaintenanceModeStatus(null);
      setMaintenanceModeError(null);
      setIsMaintenanceModeLoading(false);
      setMaintenanceModeBusyAction(null);
      return;
    }
    void refreshMaintenanceModeStatus({ silent: true });
  }, [canShowMaintenanceSyncPanel, workspacesState?.activeSandboxId]);

  useEffect(() => {
    if (!canShowMaintenanceSyncPanel) return;
    void refreshMaintenanceModeStatus({ silent: true });
  }, [
    canShowMaintenanceSyncPanel,
    currentSessionUser?.id,
    currentSessionUser?.organizationId,
    currentSessionUser?.organizationName,
    workspacesState?.activeSandboxId,
  ]);

  useEffect(() => {
    if (canShowCollabSync) return;
    setCollabBusyAction(null);
    setCollabDialogState(null);
    setCollabSelectedPaths([]);
    setCollabCommitMessage('');
    setCollabDialogError(null);
  }, [canShowCollabSync]);

  useEffect(() => {
    if (!canUseCollabSync) return;
    const normalizedRepoPath = normalizeInitialCollabRepoPath(collabRepoPath);
    if (normalizedRepoPath !== collabRepoPath) {
      setCollabRepoPath(normalizedRepoPath);
    }
  }, [canUseCollabSync, collabRepoPath]);

  useEffect(() => {
    if (!canUseCollabSync) return;
    if (collabRepoPath) {
      window.localStorage.setItem(COLLAB_REPO_PATH_STORAGE_KEY, collabRepoPath);
      return;
    }
    window.localStorage.removeItem(COLLAB_REPO_PATH_STORAGE_KEY);
  }, [canUseCollabSync, collabRepoPath]);

  useEffect(() => {
    if (!canShowCollabSync) return;
    void refreshCollabStatus(collabRepoPath);
  }, [canShowCollabSync, collabRepoPath]);

  useEffect(() => {
    if (!canShowCollabSync) return;
    const suggestedRepoPath = normalizeInitialCollabRepoPath(collabStatus?.suggestedRepoPath || null);
    if (!suggestedRepoPath) return;
    const normalizedCurrentRepoPath = normalizeInitialCollabRepoPath(collabRepoPath);
    const shouldSwitchToSuggested =
      !normalizedCurrentRepoPath
      || normalizedCurrentRepoPath !== collabRepoPath
      || (collabStatus?.isConfigured && !collabStatus.isMainBranch && suggestedRepoPath !== normalizedCurrentRepoPath);
    if (!shouldSwitchToSuggested) return;
    if (collabAutoSwitchTargetRef.current === suggestedRepoPath && normalizedCurrentRepoPath === suggestedRepoPath) return;
    collabAutoSwitchTargetRef.current = suggestedRepoPath;
    const switchingFrom = normalizedCurrentRepoPath;
    setCollabRepoPath(suggestedRepoPath);
    if (switchingFrom && switchingFrom !== suggestedRepoPath) {
      flash('info', '协作源码目录已切换到 main 基线仓库。');
    }
  }, [canShowCollabSync, collabRepoPath, collabStatus]);

  useEffect(() => {
    if (activeTab !== 'topics_management') return undefined;
    if (!candidates.some((candidate) => candidate.insightStatus === 'pending')) return undefined;
    const timer = window.setInterval(() => {
      void loadTopicsBlock().catch(() => undefined);
    }, 3000);
    return () => window.clearInterval(timer);
  }, [activeTab, candidates]);

  // 主导航只放业务模块 (5 项). 系统设置已从这里挪到侧栏底部 "账户" 区, 跟当前登录组成一组,
  // 跟业务模块视觉分开 — 避免把"系统级操作"跟日常工作流混在一起.
  const navItems = [
    { id: 'tasks' as const, label: '任务与日程', icon: CheckSquare },
    { id: 'client_workspace' as const, label: '工作台', icon: Briefcase },
    { id: 'strategic_accompaniment' as const, label: '战略陪伴', icon: Target },
    { id: 'topics_management' as const, label: '资讯情报站', icon: Newspaper },
    { id: 'growth_handbook' as const, label: '成长中心', icon: BookOpen },
  ];

  const renderWorkspaceManagerModal = () => {
    if (!workspaceManagerOpen || !canUseWorkspaceSwitcher) return null;
    const workspaces = (workspacesState?.workspaces || []).filter(
      (workspace) => workspace.kind === 'organization',
    );
    return (
      <div className="fixed inset-0 z-[88] flex items-center justify-center bg-slate-950/35 px-4">
        <div className="w-full max-w-[680px] max-h-[88vh] overflow-y-auto rounded-[24px] border border-gray-100 bg-white shadow-[0_24px_90px_rgba(15,23,42,0.18)]">
          <div className="flex items-start justify-between gap-4 border-b border-gray-100 px-7 py-6">
            <div>
              <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-[#5B7BFE]">WORKSPACE · 工作空间</p>
              <h2 className="mt-2 text-[24px] font-bold text-gray-900">工作空间管理</h2>
              <p className="mt-2 text-[13px] leading-6 text-gray-500">
                在已经登录的组织之间切换，也可以继续登录另一个组织。
              </p>
            </div>
            <button
              type="button"
              onClick={() => setWorkspaceManagerOpen(false)}
              className="inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-gray-200 bg-white text-gray-500 hover:text-gray-900"
              aria-label="关闭"
            >
              <X size={18} />
            </button>
          </div>
          <div className="space-y-3 px-7 py-6">
	            {workspaces.map((workspace) => {
	              const active = workspace.id === workspacesState?.activeSandboxId;
	              const cloudLabel = workspace.cloudApiUrl ? (cloudApiHostValue(workspace.cloudApiUrl) || '已配置云端') : '未配置云端';
	              const workspaceNeedsLogin = workspace.requiresLogin || workspace.cloudNeedsLogin || workspace.cloudConnectionStatus === 'needs_login';
	              const workspaceRetryable = workspace.cloudConnectionStatus === 'failed_retryable' || workspace.runtimeStatus === 'sync_degraded';
	              const userLabel = workspaceNeedsLogin
	                ? '需重新登录该组织'
	                : workspaceRetryable
	                ? '连接暂时失败，可重试'
	                : workspace.cloudConnected
	                ? (workspace.cloudUserFullName || workspace.cloudUserEmail || '已登录云端')
	                : '未登录云端';
              return (
                <div key={workspace.id} className={`rounded-xl border px-4 py-3 ${active ? 'border-blue-200 bg-blue-50/70' : 'border-gray-100 bg-gray-50/70'}`}>
                  <div className="flex items-start justify-between gap-3">
                    <div className="min-w-0">
                      <div className="flex flex-wrap items-center gap-2">
                        <p className="truncate text-[15px] font-semibold text-gray-950">{workspace.name}</p>
                        {active && <span className="rounded-full bg-blue-600 px-2 py-0.5 text-[10px] font-bold text-white">当前</span>}
                      </div>
                      <p className="mt-1 text-[12px] text-gray-500">组织工作空间 · {cloudLabel} · {userLabel}</p>
                      {workspace.organizationName && <p className="mt-1 text-[11px] text-gray-400">组织：{workspace.organizationName}</p>}
                    </div>
	                    {active && workspaceRetryable && (
	                      <Button disabled={workspaceManagerBusy} onClick={() => void handleActivateWorkspace(workspace.id)}>
	                        重试连接
	                      </Button>
	                    )}
	                    {!active && (
	                      <Button disabled={workspaceManagerBusy} onClick={() => void handleActivateWorkspace(workspace.id)}>
	                        {workspaceNeedsLogin ? '重新登录' : '切换'}
	                      </Button>
                    )}
                  </div>
                </div>
              );
            })}
            {workspaces.length === 0 && (
              <div className="rounded-xl border border-dashed border-gray-200 px-4 py-8 text-center text-[13px] text-gray-500">
                暂无已加入的组织。请关闭此窗口，并从左下角登录、加入或创建组织。
              </div>
            )}
            <button
              type="button"
              onClick={() => {
                setWorkspaceManagerOpen(false);
                openCloudAuthModal('login');
              }}
              className="flex w-full items-center justify-center gap-2 rounded-xl border border-dashed border-blue-200 bg-blue-50/40 px-4 py-3 text-[13px] font-semibold text-[#5B7BFE] transition hover:border-blue-300 hover:bg-blue-50"
            >
              <Plus size={15} />
              登录其他组织
            </button>
          </div>
        </div>
      </div>
    );
  };

  const renderCloudAuthModal = () => {
    if (!cloudAuthModalOpen) return null;
    const rememberedAccounts = localInputMemoryState.cloudAuth.accounts;
    const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cloudAuthForm.email);
    const cloudApiUrlValid = Boolean(cloudApiUrlFromHost(cloudAuthForm.cloudApiUrl));
    const sanitizedCloudAuthFullName = sanitizePersonNameInput(cloudAuthForm.fullName);
    const joiningWithCurrentCloudSessionInModal =
      cloudAuthAction === 'join'
      && isCloudSession
      && activeWorkspaceMatchesCloudUrl(cloudApiUrlFromHost(cloudAuthForm.cloudApiUrl));
    const loginValid =
      cloudApiUrlValid
      && Boolean(cloudAuthForm.identifier.trim())
      && cloudAuthForm.password.length >= 8;
    const identityValid =
      Boolean(sanitizedCloudAuthFullName)
      && emailValid
      && Boolean(cloudAuthForm.phone.trim())
      && cloudAuthForm.password.length >= 8;
    const joinValid =
      cloudApiUrlValid
      && Boolean(normalizeDepartmentInviteInput(cloudAuthForm.inviteCode))
      && (joiningWithCurrentCloudSessionInModal || identityValid);
    const createValid = cloudApiUrlValid && identityValid;
    const submitValid = cloudAuthAction === 'login' ? loginValid : cloudAuthAction === 'join' ? joinValid : createValid;
    const actionTitle = cloudAuthAction === 'login'
      ? '登录已有组织'
      : cloudAuthAction === 'join'
        ? '加入组织'
        : '创建或接管组织';
    const submitLabel = cloudAuthAction === 'login'
      ? '登录并进入工作空间'
      : cloudAuthAction === 'join'
        ? '加入组织并进入工作空间'
        : '进入管理员设置';
    const labeledField = (label: string, input: React.ReactNode, hint?: string, className = '') => (
      <label className={`block ${className}`}>
        <span className="mb-1.5 block text-[12px] font-semibold text-gray-700">{label}</span>
        {input}
        {hint ? <span className="mt-1.5 block text-[11px] leading-5 text-gray-500">{hint}</span> : null}
      </label>
    );
    return (
      <div className="fixed inset-0 z-[90] flex items-center justify-center bg-slate-950/35 px-4">
        <div className="w-full max-w-[720px] max-h-[88vh] overflow-y-auto rounded-[32px] border border-gray-100 bg-white shadow-[0_24px_90px_rgba(15,23,42,0.18)]">
          <div className="flex items-start justify-between gap-4 border-b border-gray-100 px-8 py-6">
            <div>
              <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-[#5B7BFE]">连接组织</p>
              <h2 className="mt-2 text-[24px] font-bold text-gray-900">{actionTitle}</h2>
              <p className="mt-2 text-[13px] leading-6 text-gray-500">
                已加入过的组织可直接登录；加入新组织需要云地址和邀请码。创建/接管只适用于新组织，或尚无管理员的组织云端。
              </p>
            </div>
            <button
              type="button"
              onClick={() => setCloudAuthModalOpen(false)}
              className="inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-gray-200 bg-white text-gray-500 hover:text-gray-900"
              aria-label="关闭"
            >
              <X size={18} />
            </button>
          </div>
          <div className="px-8 py-6 space-y-5">
            <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-100 w-fit">
              <button
                type="button"
                onClick={() => {
                  setCloudAuthAction('login');
                  setCloudAuthMessage('');
                  setOrganizationSelection(null);
                }}
                className={`px-5 py-2 rounded-xl text-[13px] font-bold ${cloudAuthAction === 'login' ? 'bg-white shadow-sm text-[#5B7BFE]' : 'text-gray-500'}`}
              >
                登录已有组织
              </button>
              <button
                type="button"
                onClick={() => {
                  setCloudAuthAction('join');
                  setCloudAuthMessage('');
                  setOrganizationSelection(null);
                }}
                className={`px-5 py-2 rounded-xl text-[13px] font-bold ${cloudAuthAction === 'join' ? 'bg-white shadow-sm text-[#5B7BFE]' : 'text-gray-500'}`}
              >
                加入组织
              </button>
              <button
                type="button"
                onClick={() => {
                  setCloudAuthAction('create');
                  setCloudAuthMessage('');
                  setOrganizationSelection(null);
                }}
                className={`px-5 py-2 rounded-xl text-[13px] font-bold ${cloudAuthAction === 'create' ? 'bg-white shadow-sm text-[#5B7BFE]' : 'text-gray-500'}`}
              >
                创建 / 接管
              </button>
            </div>

            {organizationSelection && (
              <div className="rounded-2xl border border-blue-100 bg-blue-50/70 px-4 py-4">
                <p className="text-[14px] font-bold text-gray-950">选择要进入的组织工作空间</p>
                <p className="mt-1 text-[12px] leading-5 text-gray-600">这个账号属于多个组织。请选择一个组织，软件会自动切换到对应工作空间。</p>
                <div className="mt-3 grid gap-2">
                  {organizationSelection.organizations.map((org) => (
                    <button
                      key={org.organizationId}
                      type="button"
                      disabled={cloudAuthSubmitting}
                      onClick={() => void handleSelectOrganization(org.organizationId)}
                      className="rounded-xl border border-blue-100 bg-white px-3 py-3 text-left hover:border-blue-300"
                    >
                      <div className="flex items-center justify-between gap-3">
                        <span className="text-[13px] font-semibold text-gray-900">{org.organizationName || org.organizationId}</span>
                        <span className="text-[11px] text-blue-600">{org.primaryRole === 'admin' ? '管理员' : '成员'} · {org.membershipStatus || 'approved'}</span>
                      </div>
                      <p className="mt-1 text-[11px] text-gray-500">{org.email}{org.departmentName ? ` · ${org.departmentName}` : ''}</p>
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {rememberedAccounts.length > 0 && (
                <select
                  value={cloudAuthForm.identifier}
                  onChange={(event) => {
                    const selected = rememberedAccounts.find((account) => (account.identifier || account.email) === event.target.value);
                    setCloudAuthForm((prev) => ({
                      ...prev,
                      email: selected?.email || event.target.value,
                      identifier: selected?.identifier || selected?.email || event.target.value,
                      fullName: selected?.fullName || prev.fullName,
                      password: selected?.password || '',
                      confirmPassword: selected?.password || '',
                    }));
                  }}
                  className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 text-[14px] outline-none md:col-span-2"
                >
                  <option value="">选择已记住的账号（可选）</option>
                  {rememberedAccounts.map((account) => {
                    const accountIdentifier = account.identifier || account.email;
                    return (
                    <option key={accountIdentifier} value={accountIdentifier}>
                      {account.fullName ? `${account.fullName} · ${accountIdentifier}` : accountIdentifier}
                    </option>
                  );})}
                </select>
              )}
              {labeledField('云端服务地址', (
                <input
                  value={cloudAuthForm.cloudApiUrl}
                  onChange={(event) => setCloudAuthForm((prev) => ({ ...prev, cloudApiUrl: event.target.value }))}
                  placeholder="例如 118.145.244.188 或 cloud.example.com"
                  className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 text-[14px] outline-none"
                />
              ), undefined, 'md:col-span-2')}
              {cloudAuthAction === 'create' && (
                <div className="md:col-span-2 rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-[12px] leading-5 text-amber-800 space-y-1">
                  <p className="font-semibold text-amber-900">创建/接管前请确认：</p>
                  <p>填写组织名称：创建一个新组织，并由你成为管理员。</p>
                  <p>不填组织名称：仅在该组织云尚无管理员时接管；若云端已有管理员，系统会拒绝，请向管理员索要邀请码后选择「加入组织」。</p>
                </div>
              )}
              {(
                <>
                  {cloudAuthAction === 'login' && (
                    <>
                      {labeledField('手机号或邮箱', (
                        <input
                          value={cloudAuthForm.identifier}
                          onChange={(event) => setCloudAuthForm((prev) => ({
                            ...prev,
                            identifier: event.target.value,
                            email: event.target.value.includes('@') ? event.target.value : prev.email,
                          }))}
                          placeholder="填写已加入组织的手机号或邮箱"
                          className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 text-[14px] outline-none"
                        />
                      ), undefined, 'md:col-span-2')}
                      <div className="md:col-span-2 rounded-2xl border border-blue-100 bg-blue-50/70 px-4 py-3 text-[12px] leading-5 text-blue-700">
                        换电脑或重装后，用已加入组织的手机号/邮箱和密码登录即可，不需要邀请码，也不要走“创建/接管”。
                      </div>
                    </>
                  )}
                  {cloudAuthAction === 'create' && labeledField('组织名称', (
                      <input
                        value={cloudAuthForm.organizationName}
                        onChange={(event) => setCloudAuthForm((prev) => ({ ...prev, organizationName: event.target.value }))}
                        placeholder="创建新组织时填写；接管空云端可留空"
                        className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 text-[14px] outline-none"
                      />
                    ), undefined, 'md:col-span-2')}
                  {cloudAuthAction === 'join' && (
                    <>
                      {labeledField('组织 / 部门邀请码', (
                        <input
                          value={cloudAuthForm.inviteCode}
                          onChange={(event) => setCloudAuthForm((prev) => ({ ...prev, inviteCode: event.target.value }))}
                          placeholder="填写管理员发给你的邀请码"
                          className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 text-[14px] outline-none"
                        />
                      ), undefined, 'md:col-span-2')}
                      {cloudAuthInviteStatus.message && (
                        <div className={`md:col-span-2 rounded-2xl border px-4 py-3 text-[12px] ${cloudAuthInviteStatus.valid === false ? 'border-red-200 bg-red-50 text-red-700' : 'border-blue-200 bg-blue-50 text-blue-700'}`}>
                          {cloudAuthInviteStatus.loading ? '正在识别邀请码...' : cloudAuthInviteStatus.message}
                        </div>
                      )}
                    </>
                  )}
                  {cloudAuthAction !== 'login' && (
                    <>
                      {labeledField('称呼 / 姓名', (
                        <input
                          value={cloudAuthForm.fullName}
                          onChange={(event) => setCloudAuthForm((prev) => ({ ...prev, fullName: sanitizePersonNameInput(event.target.value) }))}
                          placeholder="填写你在组织里的称呼"
                          className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 text-[14px] outline-none"
                        />
                      ))}
                      {labeledField('手机号', (
                        <input
                          value={cloudAuthForm.phone}
                          onChange={(event) => setCloudAuthForm((prev) => ({ ...prev, phone: event.target.value }))}
                          placeholder="建议填写飞书账号绑定手机号"
                          className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 text-[14px] outline-none"
                        />
                      ))}
                      {labeledField('邮箱', (
                        <input
                          value={cloudAuthForm.email}
                          onChange={(event) => setCloudAuthForm((prev) => ({ ...prev, email: event.target.value }))}
                          placeholder="用于登录和接收通知"
                          className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 text-[14px] outline-none"
                        />
                      ))}
                      <p className="md:col-span-2 -mt-2 text-[11px] leading-5 text-gray-500">
                        建议填写登录飞书时绑定的手机号，后续任务成员匹配和提醒会更稳定。
                      </p>
                    </>
                  )}
                  {labeledField('密码', (
                    <input
                      type={cloudAuthShowPassword ? 'text' : 'password'}
                      value={cloudAuthForm.password}
                      onChange={(event) => setCloudAuthForm((prev) => ({ ...prev, password: event.target.value }))}
                      placeholder="至少 8 位"
                      className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 text-[14px] outline-none"
                    />
                  ))}
                  {cloudAuthAction === 'join' && (
                    <>
                      {labeledField('职位', (
                        <input
                          value={cloudAuthForm.jobTitle}
                          onChange={(event) => setCloudAuthForm((prev) => ({ ...prev, jobTitle: event.target.value }))}
                          placeholder="可选，管理员后续也可以调整"
                          className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 text-[14px] outline-none"
                        />
                      ), undefined, 'md:col-span-2')}
                    </>
                  )}
                </>
              )}
            </div>

            <div className="flex flex-wrap items-center gap-4">
              <label className="flex items-center gap-2 text-[13px] font-medium text-gray-700">
                <input type="checkbox" checked={cloudAuthShowPassword} onChange={(event) => setCloudAuthShowPassword(event.target.checked)} />
                显示密码
              </label>
              <label className="flex items-center gap-2 text-[13px] font-medium text-gray-700">
                <input
                  type="checkbox"
                  checked={cloudAuthForm.rememberMe}
                  onChange={(event) => setCloudAuthForm((prev) => ({ ...prev, rememberMe: event.target.checked }))}
                />
                记住我的登录状态
              </label>
              <label className="flex items-center gap-2 text-[13px] font-medium text-gray-700">
                <input
                  type="checkbox"
                  checked={cloudAuthForm.rememberInputs}
                  onChange={(event) => setCloudAuthForm((prev) => ({ ...prev, rememberInputs: event.target.checked }))}
                />
                记住这组账号和密码（仅本机）
              </label>
            </div>

            {cloudAuthMessage && (
              <div className="rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-[13px] text-amber-800">
                {cloudAuthMessage}
              </div>
            )}

            <div className="flex justify-end gap-3">
              <Button onClick={() => setCloudAuthModalOpen(false)}>取消</Button>
              <Button
                primary
                onClick={() => void handleCloudAuthSubmit()}
                disabled={cloudAuthSubmitting || !submitValid}
              >
                {cloudAuthSubmitting ? <RefreshCw size={16} className="animate-spin" /> : <UserPlus size={16} />}
                {submitLabel}
              </Button>
            </div>
          </div>
        </div>
      </div>
    );
    };

  const strictPlanWorkshopState = useMemo<OrgModelSettings>(() => {
      const now = new Date().toISOString();
      const departmentRows = [...departmentOptions];
      if (
        currentSessionUser?.departmentId
        && !departmentRows.some((department) => department.id === currentSessionUser.departmentId)
      ) {
        departmentRows.push({
          id: currentSessionUser.departmentId,
          name: currentSessionUser.departmentName || '当前部门',
          color: '#5B7BFE',
        });
      }
      const departments = departmentRows.map((department) => ({
        id: department.id,
        name: department.name,
        color: department.color || '#5B7BFE',
        leaderUserId: currentSessionUser?.isDepartmentLead && currentSessionUser.departmentId === department.id
          ? (viewerAuthorization?.membershipId || null)
          : null,
        leaderName: currentSessionUser?.isDepartmentLead && currentSessionUser.departmentId === department.id
          ? currentSessionUser.fullName
          : '',
        introDocument: null,
        parentDepartmentId: null,
        mission: '',
        businessContext: '',
        teamContext: '',
        quarterPlan: {
          year: String(new Date().getFullYear()),
          quarter: (['Q1', 'Q2', 'Q3', 'Q4'] as const)[Math.ceil((new Date().getMonth() + 1) / 3) - 1],
          objective: '',
          deliverables: [],
          successMetrics: [],
          majorRisks: [],
          updatedAt: now,
        },
        quarterlyFocus: [],
        collaborationDepartmentIds: [],
        active: true,
        updatedAt: now,
      }));
      const plans: OrgDepartmentPlanSettings[] = strictPlanningCycles.map((cycle) => {
        const periodStart = cycle.periodStart || '';
        const periodEnd = cycle.periodEnd || '';
        let periodLabel = cycle.period?.trim() || periodStart.slice(0, 7);
        if (periodStart && periodEnd) {
          const start = new Date(`${periodStart}T00:00:00`);
          const end = new Date(`${periodEnd}T00:00:00`);
          const dayCount = Math.round((end.getTime() - start.getTime()) / 86_400_000) + 1;
          // 严格 GC-06 允许把周周期保存成日期范围；renderer 内部仍统一成 ISO week key，
          // 这样组织计划和任务编辑器共用同一周期类型/筛选规则，界面再显示周一—周日。
          if (cycle.periodKind === 'week' || dayCount === 7) periodLabel = isoWeekKeyForDate(start);
          else if (!cycle.period?.trim() && periodStart.slice(0, 4) === periodEnd.slice(0, 4) && dayCount > 300) periodLabel = periodStart.slice(0, 4);
        }
        return {
          id: cycle.id,
          version: cycle.version,
          departmentId: cycle.departmentId,
          clientId: cycle.clientId,
          weekLabel: periodLabel,
          ownerUserId: cycle.ownerMembershipId,
          title: cycle.title,
          summary: cycle.summary,
          majorRisks: [],
          dependencies: [],
          status: cycle.status === 'archived' ? 'closed' : cycle.status === 'published' ? 'active' : 'draft',
          items: [],
          updatedAt: now,
        };
      });
      return {
        ...EMPTY_ORG_MODEL_SETTINGS,
        organization: {
          ...EMPTY_ORG_MODEL_SETTINGS.organization,
          organizationId: currentSessionUser?.organizationId || '',
          name: currentSessionUser?.organizationName || organizationTaskName || '益语智库',
          updatedAt: now,
        },
        departments,
        departmentPlans: plans,
        updatedAt: now,
        authorityStates: {
          ...EMPTY_ORG_MODEL_SETTINGS.authorityStates,
          organizationPlans: {
            state: 'ready',
            authority: ['organizations', 'organization_memberships', 'planning_cycles', 'decision_actions'],
          },
        },
      };
  }, [
      currentSessionUser,
      departmentOptions,
      organizationTaskName,
      strictDecisionActions,
      strictPlanningCycles,
    viewerAuthorization?.membershipId,
  ]);
  const resolvePlanPeriod = (label: string) => {
      const value = label.trim();
      const week = weekBounds(value);
      if (week) {
        return {
          periodStart: week.start.toISOString().slice(0, 10),
          periodEnd: week.end.toISOString().slice(0, 10),
          periodKind: 'week',
        };
      }
      const quarter = value.match(/^(\d{4})-Q([1-4])$/i);
      if (quarter) {
        const month = (Number(quarter[2]) - 1) * 3;
        const start = new Date(Number(quarter[1]), month, 1);
        const end = new Date(Number(quarter[1]), month + 3, 0);
        return { periodStart: formatDateInputValue(start), periodEnd: formatDateInputValue(end), periodKind: 'quarter' };
      }
      if (/^\d{4}-\d{2}$/.test(value)) {
        const [year, month] = value.split('-').map(Number);
        return {
          periodStart: `${value}-01`,
          periodEnd: formatDateInputValue(new Date(year, month, 0)),
          periodKind: 'month',
        };
      }
      if (/^\d{4}$/.test(value)) {
        return { periodStart: `${value}-01-01`, periodEnd: `${value}-12-31`, periodKind: 'year' };
      }
      const today = formatDateInputValue(new Date());
      return { periodStart: today, periodEnd: today, periodKind: 'custom' };
    };

	  const handleSavePlanFromWorkshop = async (plan: OrgDepartmentPlanSettings) => {
      setIsSavingOrgModel(true);
      try {
        const existingCycle = strictPlanningCycles.find((cycle) => cycle.id === plan.id) || null;
        const period = resolvePlanPeriod(plan.weekLabel);
        const cyclePayload = {
          planningCycleId: plan.id,
          recordKind: plan.departmentId ? 'department_plan' : 'organization_plan',
          departmentId: plan.departmentId || null,
          clientId: plan.clientId || null,
          ownerMembershipId: plan.ownerUserId || viewerAuthorization?.membershipId || undefined,
          ...period,
          period: plan.weekLabel,
          title: plan.title?.trim() || plan.summary.trim() || `${plan.departmentId ? '部门' : '组织'}计划 · ${plan.weekLabel}`,
          summary: plan.summary,
          status: plan.status === 'closed' ? 'archived' : plan.status === 'active' ? 'published' : 'draft',
        };
        const savedCycle = existingCycle
          ? (await gc06Api.updatePlanningCycle(existingCycle, cyclePayload)).planningCycle
          : (await gc06Api.createPlanningCycle(cyclePayload)).planningCycle;
        const [cycles, actions] = await Promise.all([gc06Api.listPlanningCycles(true), gc06Api.listDecisionActions()]);
        setStrictPlanningCycles(cycles);
        setStrictDecisionActions(actions);
	      organizationPlanningCacheRef.current = {
	        scopeKey: [
	          currentActiveSandboxId(),
	          viewerAuthorization?.membershipId || currentSessionUser?.id || '',
	          currentSessionUser?.organizationId || '',
	        ].join('|'),
	        loadedAt: Date.now(),
	      };
	      flash('success', '计划已保存');
	    } catch (error) {
	      flash('error', error instanceof Error ? error.message : '保存失败');
	      throw error;
	    } finally {
	      setIsSavingOrgModel(false);
	    }
	  };

	  const handleDeletePlanFromWorkshop = async (plan: OrgDepartmentPlanSettings) => {
      setIsSavingOrgModel(true);
      try {
        const latestCycles = await gc06Api.listPlanningCycles(true);
        const existingCycle = latestCycles.find((cycle) => cycle.id === plan.id);
        // A missing ID in a successful authoritative snapshot means a previous
        // delete already committed. Treat repeated confirmation as idempotent.
        if (existingCycle) await gc06Api.deletePlanningCycle(existingCycle);
        const [cycles, actions] = await Promise.all([
          gc06Api.listPlanningCycles(true),
          gc06Api.listDecisionActions(),
        ]);
        setStrictPlanningCycles(cycles);
        setStrictDecisionActions(actions);
        organizationPlanningCacheRef.current = {
          scopeKey: [
            currentActiveSandboxId(),
            viewerAuthorization?.membershipId || currentSessionUser?.id || '',
            currentSessionUser?.organizationId || '',
          ].join('|'),
          loadedAt: Date.now(),
        };
        flash('success', '未关联任务的计划已删除');
      } catch (error) {
        flash('error', error instanceof Error ? error.message : '删除计划失败');
        throw error;
      } finally {
        setIsSavingOrgModel(false);
      }
	  };

