    // and permission checks behave as if the signed-in member were anonymous.
    const currentTaskMembershipId = currentViewerAuthorization?.membershipId || null;
    const buildDefaultCollaborators = (): MentionCandidate[] => {
      const membershipId = currentTaskMembershipId || '';
      if (!effectiveTaskSettings.autoAssignSelf || !currentSessionUser || !membershipId) return [];
      return [{
        id: membershipId,
        fullName: currentSessionUser.fullName,
        email: currentSessionUser.email,
        primaryRole: currentSessionUser.primaryRole,
        isSelf: true,
      }];
    };
