      const primaryReady = cloudConfigured && textModelReady;
      const ollamaReadyCount = AI_LOCAL_MODEL_PROFILE_ORDER.filter((k) => health?.aiProfiles?.[k]?.ready).length;
      const ollamaTotal = AI_LOCAL_MODEL_PROFILE_ORDER.length;
      const cloudSpeechConfigured = Boolean(speechModelSettingsState?.enabled);
      const speechStatusChip: { text: string; tone: 'success' | 'warning' | 'neutral' } = localAsrModelInstalled === null
        ? { text: '确认中', tone: 'neutral' }
        : localAsrModelInstalled
